import { randomUUID } from "crypto";
import { DateTimeString, toDateTimeString } from "../types/date-time-string";
import { ModelError } from "./model-error";

export const TELEGRAM_BOT_STATUSES = [
  /** Webhook registration in progress; not yet usable */
  "PENDING",
  /** Webhook registered and active; receives inbound messages */
  "CONNECTED",
  /** Disconnect requested; webhook being removed */
  "DELETING",
] as const;
export type TelegramBotStatus = (typeof TELEGRAM_BOT_STATUSES)[number];

// Plain data shape.
export interface TelegramBotData {
  id: string;
  userId: string;
  token: string;
  webhookSecret: string;
  status: TelegramBotStatus;
  isArchived: boolean;
  createdAt: DateTimeString;
  updatedAt: DateTimeString;
}

export class TelegramBot implements TelegramBotData {
  private readonly data: Readonly<TelegramBotData>;

  get id() {
    return this.data.id;
  }

  get userId() {
    return this.data.userId;
  }

  get token() {
    return this.data.token;
  }

  get webhookSecret() {
    return this.data.webhookSecret;
  }

  get status() {
    return this.data.status;
  }

  get isArchived() {
    return this.data.isArchived;
  }

  get createdAt() {
    return this.data.createdAt;
  }

  get updatedAt() {
    return this.data.updatedAt;
  }

  static create(
    input: CreateTelegramBotInput,
    {
      idGenerator = randomUUID,
      webhookSecretGenerator = randomUUID,
    }: {
      idGenerator?: () => string;
      webhookSecretGenerator?: () => string;
    } = {},
  ): TelegramBot {
    const now = toDateTimeString(new Date().toISOString());

    const data: TelegramBotData = {
      id: idGenerator(),
      userId: input.userId,
      token: input.token.trim(),
      webhookSecret: webhookSecretGenerator(),
      status: "PENDING",
      isArchived: false,
      createdAt: now,
      updatedAt: now,
    };

    return new TelegramBot(data);
  }

  static fromPersistence(data: Readonly<TelegramBotData>): TelegramBot {
    return new TelegramBot(data);
  }

  toData(): Readonly<TelegramBotData> {
    return {
      ...this.data,
    };
  }

  connect(): TelegramBot {
    if (this.status !== "PENDING") {
      throw new ModelError("Cannot connect bot that is not pending");
    }

    const data: TelegramBotData = {
      ...this.data,
      status: "CONNECTED",
      updatedAt: toDateTimeString(new Date().toISOString()),
    };

    return new TelegramBot(data);
  }

  disconnect(): TelegramBot {
    if (this.status !== "CONNECTED") {
      throw new ModelError("Cannot disconnect bot that is not connected");
    }

    const data: TelegramBotData = {
      ...this.data,
      status: "DELETING",
      updatedAt: toDateTimeString(new Date().toISOString()),
    };

    return new TelegramBot(data);
  }

  archive(): TelegramBot {
    if (this.isArchived) {
      throw new ModelError("Cannot archive archived telegram bot");
    }

    const now = toDateTimeString(new Date().toISOString());

    const data: TelegramBotData = {
      ...this.data,
      isArchived: true,
      updatedAt: now,
    };

    return new TelegramBot(data);
  }

  private constructor(data: Readonly<TelegramBotData>) {
    this.data = { ...data };
    this.assertInvariants();
  }

  private assertInvariants(): void {
    if (!this.token) {
      throw new ModelError("Telegram bot token is required");
    }

    if (!this.webhookSecret) {
      throw new ModelError("Telegram bot webhook secret is required");
    }
  }
}

export interface CreateTelegramBotInput {
  userId: string;
  token: string;
}

src/models/transaction.ts.source:
import { randomUUID } from "crypto";
import { DateString } from "../types/date-string";
import { DateTimeString, toDateTimeString } from "../types/date-time-string";
import { Account } from "./account";
import { Category } from "./category";
import { ModelError } from "./model-error";

export const DESCRIPTION_MAX_LENGTH = 500;

// A companion object (not a plain union) so TransactionType.XYZ stays available:
// property access is checked against these keys,
// unlike a bare string literal
// which type-checksv against nothing outside a directly-typed context
// (e.g. inside expect(...).toEqual(...)).
export const TransactionType = {
  EXPENSE: "EXPENSE",
  INCOME: "INCOME",
  REFUND: "REFUND",
  TRANSFER_IN: "TRANSFER_IN",
  TRANSFER_OUT: "TRANSFER_OUT",
} as const;

export type TransactionType =
  (typeof TransactionType)[keyof typeof TransactionType];

export type NonTransferTransactionType = Exclude<
  TransactionType,
  typeof TransactionType.TRANSFER_IN | typeof TransactionType.TRANSFER_OUT
>;

// Plain data shape.
export interface TransactionData {
  userId: string;
  id: string;
  accountId: string;
  categoryId?: string;
  type: TransactionType;
  amount: number;
  currency: string;
  date: DateString;
  description?: string;
  transferId?: string;
  compoundTransaction?: { id: string; totalAmount: number };
  isArchived: boolean;
  version: number;
  createdAt: DateTimeString;
  updatedAt: DateTimeString;
}

export class Transaction implements TransactionData {
  private readonly data: Readonly<TransactionData>;

  get userId() {
    return this.data.userId;
  }

  get id() {
    return this.data.id;
  }

  get accountId() {
    return this.data.accountId;
  }

  get categoryId() {
    return this.data.categoryId;
  }

  get type() {
    return this.data.type;
  }

  get amount() {
    return this.data.amount;
  }

  get currency() {
    return this.data.currency;
  }

  get date() {
    return this.data.date;
  }

  get description() {
    return this.data.description;
  }

  get transferId() {
    return this.data.transferId;
  }

  get compoundTransaction() {
    return this.data.compoundTransaction;
  }

  get isArchived() {
    return this.data.isArchived;
  }

  get version() {
    return this.data.version;
  }

  get createdAt() {
    return this.data.createdAt;
  }

  get updatedAt() {
    return this.data.updatedAt;
  }

  static create(
    input: CreateTransactionInput,
    { idGenerator = randomUUID }: { idGenerator?: () => string } = {},
  ): Transaction {
    const { account, category } = input;
    const now = toDateTimeString(new Date().toISOString());

    const data: TransactionData = {
      id: idGenerator(),
      userId: input.userId,
      accountId: account.id,
      categoryId: category?.id,
      type: input.type,
      amount: input.amount,
      currency: account.currency,
      date: input.date,
      description: normalizeDescription(input.description),
      transferId: input.transferId,
      compoundTransaction: input.compoundTransaction,
      isArchived: false,
      version: 0,
      createdAt: now,
      updatedAt: now,
    };

    return new Transaction(data, {
      newAccount: account,
      newCategory: category,
    });
  }

  static fromPersistence(data: Readonly<TransactionData>): Transaction {
    return new Transaction(data);
  }

  get signedAmount(): number {
    switch (this.type) {
      case "INCOME":
      case "REFUND":
      case "TRANSFER_IN":
        return this.amount;
      case "EXPENSE":
      case "TRANSFER_OUT":
        return -this.amount;
    }
  }

  isTransfer(): boolean {
    return this.type === "TRANSFER_IN" || this.type === "TRANSFER_OUT";
  }

  toData(): Readonly<TransactionData> {
    return {
      ...this.data,
    };
  }

  /**
   * Returns the version this entity will have once persisted.
   */
  nextVersion(): number {
    return this.version + 1;
  }

  bumpVersion(): Transaction {
    return new Transaction(
      {
        ...this.data,
        version: this.nextVersion(),
      },
      undefined,
      // Version bump leaves all invariant-bearing fields unchanged.
      { skipInvariants: true },
    );
  }

  update(
    input: UpdateTransactionInput,
    { currentCategory }: { currentCategory: Category | undefined },
  ): Transaction {
    if (this.isArchived) {
      throw new ModelError("Cannot update archived transaction");
    }

    if (currentCategory?.id !== this.categoryId) {
      throw new ModelError(
        "Current category does not match transaction category",
      );
    }

    const now = toDateTimeString(new Date().toISOString());

    const newCategoryId =
      input.category === undefined // Keep existing category
        ? this.categoryId
        : input.category === null // Remove category
          ? undefined
          : input.category.id;

    const newDescription =
      input.description === undefined // Keep existing description
        ? this.description
        : input.description === null // Remove description
          ? undefined
          : normalizeDescription(input.description);

    const data: TransactionData = {
      ...this.data,
      // Override account fields only when a new account is provided.
      ...(input.account && {
        accountId: input.account.id,
        currency: input.account.currency,
      }),
      categoryId: newCategoryId,
      type: input.type ?? this.type,
      amount: input.amount ?? this.amount,
      date: input.date ?? this.date,
      description: newDescription,
      updatedAt: now,
    };

    const categoryRelation =
      input.category === undefined // Keep existing category
        ? { currentCategory }
        : input.category === null // Remove category
          ? {}
          : { newCategory: input.category };

    return new Transaction(data, {
      newAccount: input.account,
      ...categoryRelation,
    });
  }

  archive(): Transaction {
    if (this.isArchived) {
      throw new ModelError("Cannot archive archived transaction");
    }

    const now = toDateTimeString(new Date().toISOString());

    const data: TransactionData = {
      ...this.data,
      isArchived: true,
      updatedAt: now,
    };

    return new Transaction(data);
  }

  private constructor(
    data: Readonly<TransactionData>,
    // A new category or a kept current category, never both.
    transientRelations?: { newAccount?: Account } & (
      | { newCategory?: Category; currentCategory?: never }
      | { newCategory?: never; currentCategory?: Category }
    ),
    { skipInvariants = false }: { skipInvariants?: boolean } = {},
  ) {
    this.data = { ...data };

    if (!skipInvariants) {
      this.assertInvariants(transientRelations);
    }
  }

  private assertInvariants(
    transientRelations?: { newAccount?: Account } & (
      | { newCategory?: Category; currentCategory?: never }
      | { newCategory?: never; currentCategory?: Category }
    ),
  ): void {
    const newAccount = transientRelations?.newAccount;
    const newCategory = transientRelations?.newCategory;
    const currentCategory = transientRelations?.currentCategory;

    if (newAccount) {
      if (newAccount.userId !== this.userId) {
        throw new ModelError("Account does not belong to user");
      }

      if (newAccount.isArchived) {
        throw new ModelError("Account must not be archived");
      }
    }

    if (this.amount <= 0) {
      throw new ModelError("Amount must be positive");
    }

    if (this.isTransfer()) {
      if (this.categoryId) {
        throw new ModelError("Transfer transactions cannot have a category");
      }

      if (this.compoundTransaction) {
        throw new ModelError(
          "Transfer transactions cannot be part of a compound transaction",
        );
      }

      if (!this.transferId) {
        throw new ModelError("Transfer transactions must include transferId");
      }
    } else {
      if (this.transferId) {
        throw new ModelError(
          "Only transfer transactions can include transferId",
        );
      }
    }

    if (newCategory) {
      if (newCategory.userId !== this.userId) {
        throw new ModelError("Category does not belong to user");
      }

      if (newCategory.isArchived) {
        throw new ModelError("Category must not be archived");
      }
    }

    // A new category replaces the current category.
    const effectiveCategory = newCategory ?? currentCategory;

    if (effectiveCategory) {
      const typeMismatch =
        (effectiveCategory.type === "INCOME" && this.type !== "INCOME") ||
        (effectiveCategory.type === "EXPENSE" &&
          this.type !== "EXPENSE" &&
          this.type !== "REFUND");

      if (typeMismatch) {
        throw new ModelError(
          `Category type "${effectiveCategory.type}" does not match transaction type "${this.type}"`,
        );
      }
    }

    if (this.description && this.description.length > DESCRIPTION_MAX_LENGTH) {
      throw new ModelError(
        `Description cannot exceed ${DESCRIPTION_MAX_LENGTH} characters`,
      );
    }

    if (this.compoundTransaction) {
      if (!this.compoundTransaction.id) {
        throw new ModelError("Compound transaction must include an id");
      }

      if (this.compoundTransaction.totalAmount <= 0) {
        throw new ModelError(
          "Compound transaction total amount must be positive",
        );
      }
    }
  }
}

export interface CreateTransactionInput {
  userId: string;
  account: Account;
  category?: Category;
  type: TransactionType;
  amount: number;
  date: DateString;
  description?: string;
  transferId?: string;
  compoundTransaction?: { id: string; totalAmount: number };
}

export interface UpdateTransactionInput {
  account?: Account;
  category?: Category | null;
  type?: TransactionType;
  amount?: number;
  date?: DateString;
  description?: string | null;
}

// Most popular combinations of account and category
// calculated based on transaction history.
export interface TransactionPattern {
  accountId: string;
  categoryId: string;
}

// Type for transactions that support transaction patterns
export const TRANSACTION_PATTERN_TYPES = [
  "INCOME",
  "EXPENSE",
  "REFUND",
] as const;
export type TransactionPatternType = (typeof TRANSACTION_PATTERN_TYPES)[number];

function normalizeDescription(description?: string | null): string | undefined {
  return description?.trim() || undefined;
}

