import { Temporal } from "temporal-polyfill";
import { Failure, Result, Success } from "ts-result";
import { Category } from "../models/category";
import { Transaction, TransactionType } from "../models/transaction";
import { CategoryRepository } from "../ports/category-repository";
import { TransactionRepository } from "../ports/transaction-repository";
import { toDateString } from "../types/date-string";

const TOP_TRANSACTIONS_LIMIT = 5;

type ReportType = "INCOME" | "EXPENSE";

export interface ByCategoryReportCurrencyBreakdown {
  currency: string;
  totalAmount: number;
  percentage: number;
}

export interface ByCategoryReportCategory {
  category?: Category;
  currencyBreakdowns: ByCategoryReportCurrencyBreakdown[];
  topTransactions: Transaction[];
  totalTransactionCount: number;
}

export interface ByCategoryReportCurrencyTotal {
  currency: string;
  totalAmount: number;
}

export interface ByCategoryReport {
  year: number;
  month?: number;
  type: ReportType;
  categories: ByCategoryReportCategory[];
  currencyTotals: ByCategoryReportCurrencyTotal[];
}

export class ByCategoryReportService {
  constructor(
    private transactionRepository: TransactionRepository,
    private categoryRepository: CategoryRepository,
  ) {}

  /**
   * Generate a monthly report aggregated by category for a given month and transaction type.
   *
   * For EXPENSE reports, this method factors in REFUND transactions to calculate net spending:
   * - Fetches both EXPENSE and REFUND transactions
   * - Calculates net amounts: sum(EXPENSE) - sum(REFUND) per category + currency
   * - Supports negative amounts when refunds exceed expenses
   *
   * For INCOME reports, behavior is unchanged:
   * - Fetches only INCOME transactions
   * - Sums amounts as-is (no refund factoring)
   *
   * @param userId - The user ID to generate the report for
   * @param year - The year (e.g., 2025)
   * @param month - The month (1-12)
   * @param type - The report type (EXPENSE or INCOME)
   * @returns Monthly report with categories and currency totals, or a failure reason
   */
  async call(
    userId: string,
    year: number,
    month: number | undefined,
    type: ReportType,
  ): Promise<Result<ByCategoryReport>> {
    if (!this.isValidYear(year)) {
      return Failure("Year must be a valid integer");
    }

    if (month !== undefined && !this.isValidMonth(month)) {
      return Failure("Month must be a valid integer between 1 and 12");
    }

    // For EXPENSE reports, fetch both EXPENSE and REFUND transactions
    // For INCOME reports, fetch only INCOME transactions
    let transactionTypesToFetch: TransactionType[];

    // Function to get signed amount based on report type
    // For EXPENSE: expenses are positive, refunds are negative
    // For INCOME: amounts are as-is
    let amountGetter: (transaction: Transaction) => number;

    if (type === "EXPENSE") {
      transactionTypesToFetch = ["EXPENSE", "REFUND"];
      // Negate to get expenses as positive, refunds as negative
      amountGetter = (transaction) => -transaction.signedAmount;
    } else if (type === "INCOME") {
      transactionTypesToFetch = ["INCOME"];
      amountGetter = (transaction) => transaction.signedAmount;
    } else {
      return Failure("Invalid report type");
    }

    const dateAfter =
      month !== undefined ? firstDayOfMonth(year, month) : firstDayOfYear(year);
    const dateBefore =
      month !== undefined ? lastDayOfMonth(year, month) : lastDayOfYear(year);

    const transactions = await this.transactionRepository.findManyByUserId(
      userId,
      {
        dateAfter,
        dateBefore,
        types: transactionTypesToFetch,
      },
    );

    if (transactions.length === 0) {
      return Success({
        year,
        month,
        type,
        categories: [],
        currencyTotals: [],
      });
    }

    // Fetch all categories and build set of included category IDs
    const allCategories =
      await this.categoryRepository.findManyWithArchivedByUserId(userId);
    const excludedCategoryIds = new Set(
      allCategories
        .filter((category) => category.excludeFromReports)
        .map((category) => category.id),
    );

    // Filter transactions to exclude those linked to excluded categories
    const includedTransactions = transactions.filter(
      (transaction) =>
        !transaction.categoryId ||
        !excludedCategoryIds.has(transaction.categoryId),
    );

    const currencyTotals = this.calculateCurrencyTotals(
      includedTransactions,
      amountGetter,
    );

    const categoryRows = this.groupByCategoryAndCurrency({
      transactions: includedTransactions,
      categories: allCategories,
      currencyTotals,
      amountGetter,
    });

    return Success({
      year,
      month,
      type,
      categories: categoryRows,
      currencyTotals,
    });
  }

  private calculateCurrencyTotals(
    transactions: Transaction[],
    amountGetter: (t: Transaction) => number,
  ): ByCategoryReportCurrencyTotal[] {
    const totals = new Map<string, number>();

    for (const transaction of transactions) {
      const current = totals.get(transaction.currency) || 0;
      const amount = amountGetter(transaction);
      totals.set(transaction.currency, current + amount);
    }

    return Array.from(totals.entries())
      .map(([currency, totalAmount]) => ({ currency, totalAmount }))
      .sort((a, b) => a.currency.localeCompare(b.currency));
  }

  private groupByCategoryAndCurrency({
    transactions,
    categories,
    currencyTotals,
    amountGetter,
  }: {
    transactions: Transaction[];
    categories: Category[];
    currencyTotals: ByCategoryReportCurrencyTotal[];
    amountGetter: (t: Transaction) => number;
  }): ByCategoryReportCategory[] {
    const categoryById = new Map(
      categories.map((category) => [category.id, category]),
    );

    const categoryGroups = new Map<
      string | undefined,
      { category?: Category; transactions: Transaction[] }
    >();

    for (const transaction of transactions) {
      // A category ID with no record joins the group without a category
      const category = transaction.categoryId
        ? categoryById.get(transaction.categoryId)
        : undefined;
      const categoryId = category?.id;
      const existing = categoryGroups.get(categoryId) || {
        category,
        transactions: [],
      };
      existing.transactions.push(transaction);
      categoryGroups.set(categoryId, existing);
    }

    const categoryRows: ByCategoryReportCategory[] = [];

    for (const {
      category,
      transactions: categoryTransactions,
    } of categoryGroups.values()) {
      const currencyBreakdowns = this.calculateCurrencyBreakdowns(
        categoryTransactions,
        currencyTotals,
        amountGetter,
      );

      // Get top 5 transactions by amount
      const topTransactions = categoryTransactions
        .sort((a, b) => b.amount - a.amount)
        .slice(0, TOP_TRANSACTIONS_LIMIT);

      categoryRows.push({
        category,
        currencyBreakdowns,
        topTransactions,
        totalTransactionCount: categoryTransactions.length,
      });
    }

    // Groups with a category sort by name, the group without a category is last
    return categoryRows.sort((a, b) => {
      if (!a.category) return b.category ? 1 : 0;
      if (!b.category) return -1;
      return a.category.name.localeCompare(b.category.name);
    });
  }

  private calculateCurrencyBreakdowns(
    transactions: Transaction[],
    currencyTotals: ByCategoryReportCurrencyTotal[],
    amountGetter: (t: Transaction) => number,
  ): ByCategoryReportCurrencyBreakdown[] {
    const categoryTotals = new Map<string, number>();

    for (const transaction of transactions) {
      const current = categoryTotals.get(transaction.currency) || 0;
      const amount = amountGetter(transaction);
      categoryTotals.set(transaction.currency, current + amount);
    }

    const breakdowns: ByCategoryReportCurrencyBreakdown[] = [];

    for (const [currency, totalAmount] of categoryTotals) {
      const currencyTotal = currencyTotals.find(
        (ct) => ct.currency === currency,
      );
      const percentage =
        currencyTotal && currencyTotal.totalAmount !== 0
          ? Math.round((totalAmount / currencyTotal.totalAmount) * 100)
          : 0;

      breakdowns.push({
        currency,
        totalAmount,
        percentage,
      });
    }

    return breakdowns.sort((a, b) => a.currency.localeCompare(b.currency));
  }

  private isValidYear(year: number): boolean {
    return Number.isInteger(year) && year >= 1000 && year <= 9999;
  }

  private isValidMonth(month: number): boolean {
    return Number.isInteger(month) && month >= 1 && month <= 12;
  }
}

function firstDayOfMonth(year: number, month: number) {
  const yearMonth = Temporal.PlainYearMonth.from({ year, month });
  return toDateString(yearMonth.toPlainDate({ day: 1 }).toString());
}

function firstDayOfYear(year: number) {
  return firstDayOfMonth(year, 1);
}

function lastDayOfMonth(year: number, month: number) {
  const yearMonth = Temporal.PlainYearMonth.from({ year, month });
  return toDateString(
    yearMonth.toPlainDate({ day: yearMonth.daysInMonth }).toString(),
  );
}

function lastDayOfYear(year: number) {
  return lastDayOfMonth(year, 12);
}

src/services/category-service.ts.source:
import { Failure, Result, Success } from "ts-result";
import {
  Category,
  CategoryType,
  CreateCategoryInput,
  UpdateCategoryInput,
} from "../models/category";
import { ModelError } from "../models/model-error";
import { CategoryRepository } from "../ports/category-repository";
import { TransactionRepository } from "../ports/transaction-repository";
import { EntityScope } from "../types/entity-scope";

export interface CategoryService {
  getCategoriesByUser(
    userId: string,
    filters: { scope: EntityScope; type?: CategoryType },
  ): Promise<Result<Category[]>>;
  createCategory(input: CreateCategoryInput): Promise<Result<Category>>;
  updateCategory(
    id: string,
    userId: string,
    input: UpdateCategoryInput,
  ): Promise<Result<Category>>;
  deleteCategory(id: string, userId: string): Promise<Result<Category>>;
}

/**
 * Category service class for handling business logic
 * Implements the service layer pattern for category operations
 */
export class CategoryServiceImpl implements CategoryService {
  constructor(
    private categoryRepository: CategoryRepository,
    private transactionRepository: TransactionRepository,
  ) {}

  /**
   * Get categories for a user filtered by scope, optionally filtered by type
   * Categories are sorted alphabetically by name (case-insensitive)
   * @param userId - The user ID to fetch categories for
   * @param filters.scope - Which categories to include (active, archived, or all)
   * @param filters.type - Optional category type filter (INCOME or EXPENSE)
   * @returns Categories matching the scope and type
   */
  async getCategoriesByUser(
    userId: string,
    { scope, type }: { scope: EntityScope; type?: CategoryType },
  ): Promise<Result<Category[]>> {
    if (scope === "ACTIVE") {
      return Success(
        await this.categoryRepository.findManyByUserId(userId, {
          type,
        }),
      );
    }

    const categories =
      await this.categoryRepository.findManyWithArchivedByUserId(userId);

    const scoped =
      scope === "ALL"
        ? categories
        : categories.filter((category) => category.isArchived);

    return Success(
      type ? scoped.filter((category) => category.type === type) : scoped,
    );
  }

  /**
   * Create a new category for a user
   * @param input - Category creation input
   * @returns The created category, or a failure reason
   */
  async createCategory(input: CreateCategoryInput): Promise<Result<Category>> {
    const categoryResult = Result.fromThrowable(ModelError, () =>
      Category.create(input),
    );
    if (!categoryResult.success) return categoryResult;

    const category = categoryResult.data;

    if (await this.isDuplicateName(category.userId, category.name)) {
      return Failure(`Category "${category.name}" already exists`);
    }

    await this.categoryRepository.create(category);
    return Success(category);
  }

  /**
   * Update a category
   * @param id - Category ID to update
   * @param userId - User ID for authorization
   * @param input - Category update input
   * @returns The updated category, or a failure reason
   */
  async updateCategory(
    id: string,
    userId: string,
    input: UpdateCategoryInput,
  ): Promise<Result<Category>> {
    const existingCategory = await this.categoryRepository.findOneById({
      id,
      userId,
    });

    if (!existingCategory) {
      return Failure("Category not found");
    }

    const updatedCategoryResult = Result.fromThrowable(ModelError, () =>
      existingCategory.update(input),
    );
    if (!updatedCategoryResult.success) return updatedCategoryResult;

    const updatedCategory = updatedCategoryResult.data;

    // Check for duplicate names if name is being updated
    if (
      updatedCategory.name !== existingCategory.name &&
      (await this.isDuplicateName(userId, updatedCategory.name, id))
    ) {
      return Failure(`Category "${updatedCategory.name}" already exists`);
    }

    if (
      updatedCategory.type !== existingCategory.type &&
      (await this.transactionRepository.hasTransactionsForCategory({
        categoryId: id,
        userId,
      }))
    ) {
      return Failure("Cannot change type of category with transactions");
    }

    return Success(await this.categoryRepository.update(updatedCategory));
  }

  /**
   * Archive (soft-delete) a category
   * @param id - Category ID to archive
   * @param userId - User ID for authorization
   * @returns The archived category, or a failure reason
   */
  async deleteCategory(id: string, userId: string): Promise<Result<Category>> {
    const existingCategory = await this.categoryRepository.findOneById({
      id,
      userId,
    });

    if (!existingCategory) {
      return Failure("Category not found");
    }

    const archivedCategoryResult = Result.fromThrowable(ModelError, () =>
      existingCategory.archive(),
    );
    if (!archivedCategoryResult.success) return archivedCategoryResult;

    const archivedCategory = archivedCategoryResult.data;

    return Success(await this.categoryRepository.update(archivedCategory));
  }

  private async isDuplicateName(
    userId: string,
    name: string,
    excludeId?: string,
  ): Promise<boolean> {
    const existingCategories =
      await this.categoryRepository.findManyByUserId(userId);

    const duplicateCategory = existingCategories.find(
      (category) =>
        category.name.toLowerCase() === name.toLowerCase() &&
        category.id !== excludeId,
    );

    return Boolean(duplicateCategory);
  }
}

src/services/create-transaction-from-tex.source:
import { Temporal } from "temporal-polyfill";
import { Failure, Result, Success } from "ts-result";
import { z } from "zod";
import { CREATE_TRANSACTION_TOOL_NAME } from "../langchain/tools/create-transaction";
import { Transaction } from "../models/transaction";
import { Agent, AgentTraceMessage } from "../ports/agent-types";
import { TransactionService } from "./transaction-service";

const createdTransactionSchema = z.discriminatedUnion("success", [
  z.object({
    success: z.literal(true),
    data: z.object({
      id: z.string(),
    }),
  }),
  z.object({
    success: z.literal(false),
    error: z.string(),
  }),
]);

interface CreateTransactionFromTextInput {
  isVoiceInput?: boolean;
  text: string;
  userId: string;
}

type CreateTransactionFromTextOutput = Result<
  { transaction: Transaction; agentTrace: AgentTraceMessage[] },
  { message: string; agentTrace: AgentTraceMessage[] }
>;

export class CreateTransactionFromTextService {
  private createTransactionAgent: Agent<{
    isVoiceInput: boolean;
    today: string;
    userId: string;
  }>;
  private transactionService: TransactionService;

  constructor({
    createTransactionAgent,
    transactionService,
  }: {
    createTransactionAgent: Agent<{
      isVoiceInput: boolean;
      today: string;
      userId: string;
    }>;
    transactionService: TransactionService;
  }) {
    this.createTransactionAgent = createTransactionAgent;
    this.transactionService = transactionService;
  }

  async call({
    userId,
    text,
    isVoiceInput = false,
  }: CreateTransactionFromTextInput): Promise<CreateTransactionFromTextOutput> {
    if (!userId) {
      return Failure({ message: "User ID is required", agentTrace: [] });
    }

    const normalizedText = text.trim();
    if (!normalizedText) {
      return Failure({ message: "Text is required", agentTrace: [] });
    }

    const response = await this.createTransactionAgent.invoke(
      { messages: [{ role: "user", content: normalizedText }] },
      {
        context: {
          userId,
          isVoiceInput,
          today: Temporal.Now.plainDateISO().toString(),
        },
      },
    );

    const { answer: rawAnswer, agentTrace, toolExecutions } = response;
    const answer = rawAnswer?.trim();

    const lastCreateTransactionToolExecution = toolExecutions.findLast(
      (toolExecution) => toolExecution.tool === CREATE_TRANSACTION_TOOL_NAME,
    );

    if (!lastCreateTransactionToolExecution) {
      console.log("Agent error", {
        error: "Agent did not attempt to create a transaction",
        agentAnswer: answer,
      });

      return Failure({
        message:
          "Agent did not attempt to create a transaction" +
          (answer ? `\n${answer}` : ""),
        agentTrace,
      });
    }

    let transactionDataJson;
    try {
      transactionDataJson = JSON.parse(
        lastCreateTransactionToolExecution.output,
      );
    } catch (error) {
      console.log("Agent error", {
        error: error instanceof Error ? error.message : String(error),
        agentAnswer: answer,
        toolOutput: lastCreateTransactionToolExecution.output,
      });

      return Failure({
        message: "Response from agent is not valid JSON",
        agentTrace,
      });
    }

    const parsedTransactionData =
      createdTransactionSchema.safeParse(transactionDataJson);

    if (!parsedTransactionData.success) {
      console.log("Agent error", {
        error: z.prettifyError(parsedTransactionData.error),
        agentAnswer: answer,
        toolOutput: lastCreateTransactionToolExecution.output,
      });

      return Failure({
        message: "Response from agent does not match expected format",
        agentTrace,
      });
    }

    // Tool responded with a failure
    if (!parsedTransactionData.data.success) {
      console.log("Agent error", {
        error: parsedTransactionData.data.error,
        agentAnswer: answer,
        toolOutput: lastCreateTransactionToolExecution.output,
      });

      return Failure({
        message: "Agent failed to create transaction",
        agentTrace,
      });
    }

    const transactionId = parsedTransactionData.data.data.id;

    const transactionResult = await this.transactionService.getTransactionById(
      transactionId,
      userId,
    );

    if (!transactionResult.success) {
      return Failure({ message: transactionResult.error, agentTrace });
    }

    return Success({ transaction: transactionResult.data, agentTrace });
  }
}

