import { beforeEach, describe, expect, it, vi } from "vitest";
import { HttpTelegramApiClient } from "./http-telegram-api-client";

const mockFetch = vi.fn<typeof fetch>();
global.fetch = mockFetch as unknown as typeof fetch;

function mockResponse(body: unknown, status = 200): Response {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: async () => body,
  } as Response;
}

describe("HttpTelegramApiClient", () => {
  const baseUrl = "https://api.telegram.test";

  let client: HttpTelegramApiClient;

  beforeEach(() => {
    client = new HttpTelegramApiClient(baseUrl);
    mockFetch.mockReset();
  });

  describe("getWebhookInfo", () => {
    it("calls Telegram getWebhookInfo endpoint and returns webhook info", async () => {
      const webhookInfo = { url: "https://example.com/webhooks/telegram" };
      mockFetch.mockResolvedValue(
        mockResponse({ ok: true, result: webhookInfo }),
      );

      const result = await client.getWebhookInfo("token-12345");

      expect(result).toBeSuccess(webhookInfo);
      expect(mockFetch).toHaveBeenCalledWith(
        `${baseUrl}/bottoken-12345/getWebhookInfo`,
      );
    });

    it("returns failure when Telegram returns ok: false", async () => {
      mockFetch.mockResolvedValue(
        mockResponse({ ok: false, description: "Some error" }),
      );

      const result = await client.getWebhookInfo("token-12345");

      expect(result).toBeFailure("Telegram getWebhookInfo failed: Some error");
    });

    it("returns failure when response has unexpected format", async () => {
      mockFetch.mockResolvedValue(mockResponse({ status: "error" }));

      const result = await client.getWebhookInfo("token-12345");

      expect(result).toBeFailure(
        "Telegram getWebhookInfo returned unexpected response format",
      );
    });

    it("returns failure when HTTP status is not ok", async () => {
      mockFetch.mockResolvedValue(mockResponse({}, 500));

      const result = await client.getWebhookInfo("token-12345");

      expect(result).toBeFailure("Telegram getWebhookInfo failed: HTTP 500");
    });

    it("returns failure when fetch throws", async () => {
      mockFetch.mockRejectedValue(new Error("Network error"));

      const result = await client.getWebhookInfo("token-12345");

      expect(result).toBeFailure(
        "Telegram getWebhookInfo failed: Error: Network error",
      );
    });
  });

  describe("setWebhook", () => {
    const params = {
      token: "token-12345",
      url: "https://example.com/webhooks/telegram",
      secretToken: "secret-67890",
    };

    it("calls Telegram setWebhook endpoint", async () => {
      mockFetch.mockResolvedValue(mockResponse({ ok: true }));

      const result = await client.setWebhook(params);

      expect(result).toBeSuccess(undefined);
      expect(mockFetch).toHaveBeenCalledWith(
        `${baseUrl}/bottoken-12345/setWebhook`,
        expect.objectContaining({
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            url: "https://example.com/webhooks/telegram",
            secret_token: "secret-67890",
          }),
        }),
      );
    });

    it("returns failure when Telegram returns ok: false", async () => {
      mockFetch.mockResolvedValue(
        mockResponse({ ok: false, description: "Some error" }),
      );

      const result = await client.setWebhook(params);

      expect(result).toBeFailure("Telegram setWebhook failed: Some error");
    });

    it("returns failure when response has unexpected format", async () => {
      mockFetch.mockResolvedValue(mockResponse({ status: "error" }));

      const result = await client.setWebhook(params);

      expect(result).toBeFailure(
        "Telegram setWebhook returned unexpected response format",
      );
    });

    it("returns failure when HTTP status is not ok", async () => {
      mockFetch.mockResolvedValue(mockResponse({}, 500));

      const result = await client.setWebhook(params);

      expect(result).toBeFailure("Telegram setWebhook failed: HTTP 500");
    });

    it("returns failure when fetch throws", async () => {
      mockFetch.mockRejectedValue(new Error("Network error"));

      const result = await client.setWebhook(params);

      expect(result).toBeFailure(
        "Telegram setWebhook failed: Error: Network error",
      );
    });
  });

  describe("deleteWebhook", () => {
    it("calls Telegram deleteWebhook endpoint", async () => {
      mockFetch.mockResolvedValue(mockResponse({ ok: true }));

      const result = await client.deleteWebhook("token-12345");

      expect(result).toBeSuccess(undefined);
      expect(mockFetch).toHaveBeenCalledWith(
        `${baseUrl}/bottoken-12345/deleteWebhook`,
