import { faker } from "@faker-js/faker";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { toDateString } from "../types/date-string";
import { toDateTimeString } from "../types/date-time-string";
import { fakeAccount } from "../utils/test-utils/models/account-fakes";
import { fakeCategory } from "../utils/test-utils/models/category-fakes";
import {
  fakeCreateTransactionInput,
  fakeExpense,
  fakeIncome,
  fakeRefund,
  fakeTransaction,
  fakeTransferIn,
  fakeTransferOut,
} from "../utils/test-utils/models/transaction-fakes";
import { ModelError } from "./model-error";
import {
  DESCRIPTION_MAX_LENGTH,
  Transaction,
  TransactionType,
} from "./transaction";

describe("Transaction", () => {
  describe("create", () => {
    beforeEach(() => {
      vi.useFakeTimers().setSystemTime(new Date("2000-01-02T10:11:12.000Z"));
    });

    afterEach(() => {
      vi.useRealTimers();
    });

    const fixedDeps = { idGenerator: () => "fixed-uuid" };

    // Happy path

    it("builds transaction with all fields populated", () => {
      // Arrange
      const userId = faker.string.uuid();
      const account = fakeAccount({ userId, currency: "EUR" });
      const category = fakeCategory({ userId, type: "EXPENSE" });
      const input = fakeCreateTransactionInput({
        userId,
        account,
        category,
        type: "EXPENSE",
        amount: 42.5,
        date: toDateString("2000-01-02"),
        description: "lunch",
      });

      // Act
      const result = Transaction.create(input, fixedDeps);

      // Assert
      expect(result.toData()).toEqual({
        id: "fixed-uuid",
        userId,
        accountId: account.id,
        categoryId: category.id,
        type: "EXPENSE",
        amount: 42.5,
        currency: "EUR",
        date: "2000-01-02",
        description: "lunch",
        transferId: undefined,
        isArchived: false,
        version: 0,
        createdAt: "2000-01-02T10:11:12.000Z",
        updatedAt: "2000-01-02T10:11:12.000Z",
      });
    });

    it("builds transaction without category", () => {
      // Act
      const result = Transaction.create(
        fakeCreateTransactionInput({ category: undefined }),
        fixedDeps,
      );

      // Assert
      expect(result.categoryId).toBeUndefined();
    });

    it("derives currency from account", () => {
      // Arrange
      const account = fakeAccount({ currency: "GBP" });

      // Act
      const result = Transaction.create(
        fakeCreateTransactionInput({ userId: account.userId, account }),
        fixedDeps,
      );

      // Assert
      expect(result.currency).toBe("GBP");
    });

    it("trims description", () => {
      // Act
      const result = Transaction.create(
        fakeCreateTransactionInput({ description: "  spaced  " }),
        fixedDeps,
      );

      // Assert
      expect(result.description).toBe("spaced");
    });

    it("accepts whitespace-padded description within limit after trim", () => {
      // Arrange
      const withinLimit = "x".repeat(DESCRIPTION_MAX_LENGTH);
      const padded = `  ${withinLimit}  `;

      // Act
      const result = Transaction.create(
        fakeCreateTransactionInput({ description: padded }),
        fixedDeps,
      );

      // Assert
      expect(result.description).toBe(withinLimit);
    });

    it("sets description to undefined when empty after trim", () => {
      // Act
      const result = Transaction.create(
        fakeCreateTransactionInput({ description: "   " }),
        fixedDeps,
      );

      // Assert
      expect(result.description).toBeUndefined();
    });

    it("uses default id generator when omitted", () => {
      // Act
      const result = Transaction.create(fakeCreateTransactionInput());

      // Assert
      expect(result.id).toBeDefined();
    });

    it("builds REFUND transaction with EXPENSE category", () => {
      // Arrange
      const userId = faker.string.uuid();
      const account = fakeAccount({ userId });
      const category = fakeCategory({ userId, type: "EXPENSE" });

      // Act
      const result = Transaction.create(
        fakeCreateTransactionInput({
          userId,
          account,
          category,
          type: "REFUND",
        }),
        fixedDeps,
      );

      // Assert
      expect(result.type).toBe(TransactionType.REFUND);
      expect(result.categoryId).toBe(category.id);
    });

    it("builds TRANSFER_OUT transaction with transferId", () => {
      // Arrange
      const transferId = faker.string.uuid();

      // Act
      const result = Transaction.create(
        fakeCreateTransactionInput({
          type: "TRANSFER_OUT",
          transferId,
        }),
        fixedDeps,
      );

      // Assert
      expect(result.type).toBe(TransactionType.TRANSFER_OUT);
      expect(result.transferId).toBe(transferId);
      expect(result.categoryId).toBeUndefined();
    });

    it("builds TRANSFER_IN transaction with transferId", () => {
      // Arrange
      const transferId = faker.string.uuid();

      // Act
      const result = Transaction.create(
        fakeCreateTransactionInput({
          type: "TRANSFER_IN",
          transferId,
        }),
        fixedDeps,
      );

      // Assert
      expect(result.type).toBe(TransactionType.TRANSFER_IN);
      expect(result.transferId).toBe(transferId);
    });

    it("builds non-transfer transaction with compoundTransaction", () => {
      // Arrange
      const compoundTransaction = {
        id: faker.string.uuid(),
        totalAmount: 15,
      };

      // Act
      const result = Transaction.create(
        fakeCreateTransactionInput({
          type: faker.helpers.arrayElement(["EXPENSE", "INCOME", "REFUND"]),
          compoundTransaction,
        }),
        fixedDeps,
      );

      // Assert
      expect(result.compoundTransaction).toEqual(compoundTransaction);
    });

    // Validation failures

    it("throws when account belongs to different user", () => {
      // Arrange
      const account = fakeAccount({ userId: faker.string.uuid() });

      // Act & Assert
      expect(() =>
        Transaction.create(
          fakeCreateTransactionInput({
            userId: faker.string.uuid(),
            account,
          }),
          fixedDeps,
        ),
      ).toThrow(new ModelError("Account does not belong to user"));
    });

    it("throws when account is archived", () => {
      // Arrange
      const userId = faker.string.uuid();
      const account = fakeAccount({ userId, isArchived: true });

      // Act & Assert
      expect(() =>
        Transaction.create(
          fakeCreateTransactionInput({ userId, account }),
          fixedDeps,
        ),
      ).toThrow(new ModelError("Account must not be archived"));
    });

    it("throws on zero amount", () => {
      // Act & Assert
      expect(() =>
        Transaction.create(
          fakeCreateTransactionInput({ amount: 0 }),
          fixedDeps,
        ),
      ).toThrow(new ModelError("Amount must be positive"));
    });

    it("throws on negative amount", () => {
      // Act & Assert
      expect(() =>
        Transaction.create(
          fakeCreateTransactionInput({ amount: -5 }),
          fixedDeps,
        ),
      ).toThrow(new ModelError("Amount must be positive"));
    });

    it("throws when category belongs to different user", () => {
      // Arrange
      const userId = faker.string.uuid();
      const category = fakeCategory({
        userId: faker.string.uuid(),
        type: "EXPENSE",
      });

      // Act & Assert
      expect(() =>
        Transaction.create(
          fakeCreateTransactionInput({ userId, category }),
          fixedDeps,
        ),
      ).toThrow(new ModelError("Category does not belong to user"));
    });

    it("throws when category is archived", () => {
      // Arrange
      const userId = faker.string.uuid();
      const category = fakeCategory({
        userId,
        type: "EXPENSE",
        isArchived: true,
      });

      // Act & Assert
      expect(() =>
        Transaction.create(
          fakeCreateTransactionInput({ userId, category }),
          fixedDeps,
        ),
      ).toThrow(new ModelError("Category must not be archived"));
    });

    it("throws on INCOME category for EXPENSE transaction", () => {
      // Arrange
      const userId = faker.string.uuid();
      const category = fakeCategory({ userId, type: "INCOME" });

      // Act & Assert
      expect(() =>
        Transaction.create(
          fakeCreateTransactionInput({
            userId,
            category,
            type: "EXPENSE",
          }),
          fixedDeps,
        ),
      ).toThrow(
        new ModelError(
          'Category type "INCOME" does not match transaction type "EXPENSE"',
        ),
      );
    });

    it("throws on EXPENSE category for INCOME transaction", () => {
      // Arrange
      const userId = faker.string.uuid();
      const category = fakeCategory({ userId, type: "EXPENSE" });

      // Act & Assert
      expect(() =>
        Transaction.create(
          fakeCreateTransactionInput({
            userId,
            category,
            type: "INCOME",
          }),
          fixedDeps,
        ),
      ).toThrow(
        new ModelError(
          'Category type "EXPENSE" does not match transaction type "INCOME"',
        ),
      );
    });

    it("throws when description exceeds maximum length", () => {
      // Arrange
      const tooLong = "x".repeat(DESCRIPTION_MAX_LENGTH + 1);

      // Act & Assert
      expect(() =>
        Transaction.create(
          fakeCreateTransactionInput({ description: tooLong }),
          fixedDeps,
        ),
      ).toThrow(
        new ModelError(
          `Description cannot exceed ${DESCRIPTION_MAX_LENGTH} characters`,
        ),
      );
    });

    it("throws on transfer with category", () => {
      // Arrange
      const userId = faker.string.uuid();
      const account = fakeAccount({ userId });
      const category = fakeCategory({ userId, type: "EXPENSE" });

      // Act & Assert
      expect(() =>
        Transaction.create(
          fakeCreateTransactionInput({
            userId,
            account,
            category,
            type: "TRANSFER_OUT",
            transferId: faker.string.uuid(),
          }),
          fixedDeps,
        ),
      ).toThrow(new ModelError("Transfer transactions cannot have a category"));
    });

    it("throws on transfer without transferId", () => {
      // Act & Assert
      expect(() =>
        Transaction.create(
          fakeCreateTransactionInput({
            type: "TRANSFER_OUT",
            transferId: undefined,
          }),
          fixedDeps,
        ),
      ).toThrow(
        new ModelError("Transfer transactions must include transferId"),
      );
    });

    it("throws on non-transfer with transferId", () => {
      // Act & Assert
      expect(() =>
        Transaction.create(
          fakeCreateTransactionInput({
            type: "EXPENSE",
            transferId: faker.string.uuid(),
          }),
          fixedDeps,
        ),
      ).toThrow(
        new ModelError("Only transfer transactions can include transferId"),
      );
    });

    it("throws on transfer with compoundTransaction", () => {
      // Act & Assert
      expect(() =>
        Transaction.create(
          fakeCreateTransactionInput({
            type: faker.helpers.arrayElement(["TRANSFER_IN", "TRANSFER_OUT"]),
            transferId: faker.string.uuid(),
            compoundTransaction: { id: faker.string.uuid(), totalAmount: 15 },
          }),
        ),
      ).toThrow(
        new ModelError(
          "Transfer transactions cannot be part of a compound transaction",
        ),
      );
    });

    it("throws on empty compoundTransaction id", () => {
      // Act & Assert
      expect(() =>
        Transaction.create(
          fakeCreateTransactionInput({
            type: "EXPENSE",
            compoundTransaction: { id: "", totalAmount: 15 },
          }),
          fixedDeps,
        ),
      ).toThrow(new ModelError("Compound transaction must include an id"));
    });

    it("throws on zero compoundTransaction totalAmount", () => {
      // Act & Assert
      expect(() =>
        Transaction.create(
          fakeCreateTransactionInput({
            type: "EXPENSE",
            compoundTransaction: { id: faker.string.uuid(), totalAmount: 0 },
          }),
          fixedDeps,
        ),
      ).toThrow(
        new ModelError("Compound transaction total amount must be positive"),
      );
    });

    it("throws on negative compoundTransaction totalAmount", () => {
      // Act & Assert
      expect(() =>
        Transaction.create(
          fakeCreateTransactionInput({
            type: "EXPENSE",
            compoundTransaction: { id: faker.string.uuid(), totalAmount: -100 },
          }),
          fixedDeps,
        ),
      ).toThrow(
        new ModelError("Compound transaction total amount must be positive"),
      );
    });
  });

  describe("fromPersistence", () => {
    // Happy path

    it("reconstructs instance from data", () => {
      // Arrange
      const data = fakeTransaction().toData();

      // Act
      const result = Transaction.fromPersistence(data);

      // Assert
      expect(result.toData()).toEqual(data);
    });

    // Validation failures

    it("throws on zero amount", () => {
      // Arrange
      const data = { ...fakeTransaction().toData(), amount: 0 };

      // Act & Assert
      expect(() => Transaction.fromPersistence(data)).toThrow(
        new ModelError("Amount must be positive"),
      );
    });

    it("throws when transfer has categoryId", () => {
      // Arrange
      const data = {
        ...fakeTransferOut({}).toData(),
        categoryId: faker.string.uuid(),
      };

      // Act & Assert
      expect(() => Transaction.fromPersistence(data)).toThrow(
        new ModelError("Transfer transactions cannot have a category"),
      );
    });

    it("throws when transfer has compoundTransaction", () => {
      // Arrange
      const data = {
        ...fakeTransferOut({}).toData(),
        compoundTransaction: { id: faker.string.uuid(), totalAmount: 15 },
      };

      // Act & Assert
      expect(() => Transaction.fromPersistence(data)).toThrow(
        new ModelError(
          "Transfer transactions cannot be part of a compound transaction",
        ),
      );
    });
  });

  describe("signedAmount", () => {
    // Happy path

    it("returns positive amount for INCOME transactions", () => {
      // Arrange
      const tx = fakeIncome({
        amount: 100,
      });

      // Act & Assert
      expect(tx.signedAmount).toBe(100);
    });

    it("returns positive amount for REFUND transactions", () => {
      // Arrange
      const tx = fakeRefund({
        amount: 100,
      });

      // Act & Assert
      expect(tx.signedAmount).toBe(100);
    });

    it("returns positive amount for TRANSFER_IN transactions", () => {
      // Arrange
      const tx = fakeTransferIn({
        amount: 100,
      });

      // Act & Assert
      expect(tx.signedAmount).toBe(100);
    });

    it("returns negative amount for EXPENSE transactions", () => {
      // Arrange
      const tx = fakeExpense({
        amount: 100,
      });

      // Act & Assert
      expect(tx.signedAmount).toBe(-100);
    });

    it("returns negative amount for TRANSFER_OUT transactions", () => {
      // Arrange
      const tx = fakeTransferOut({
        amount: 100,
      });

      // Act & Assert
      expect(tx.signedAmount).toBe(-100);
    });
  });

  describe("isTransfer", () => {
    // Happy path

    it("returns true for TRANSFER_IN transactions", () => {
      expect(fakeTransferIn().isTransfer()).toBe(true);
    });

    it("returns true for TRANSFER_OUT transactions", () => {
      expect(fakeTransferOut().isTransfer()).toBe(true);
    });

    it("returns false for INCOME transactions", () => {
      expect(fakeIncome().isTransfer()).toBe(false);
    });

    it("returns false for EXPENSE transactions", () => {
      expect(fakeExpense().isTransfer()).toBe(false);
    });

    it("returns false for REFUND transactions", () => {
      expect(fakeRefund().isTransfer()).toBe(false);
    });
  });

  describe("toData", () => {
    // Happy path

    it("returns plain object with all data fields", () => {
      // Arrange
      const data = fakeTransaction().toData();
      const tx = Transaction.fromPersistence(data);

      // Act & Assert
      expect(tx.toData()).toEqual(data);
    });
  });

  describe("nextVersion", () => {
    // Happy path

    it("returns version plus 1", () => {
      // Arrange
      const tx = fakeTransaction({ version: 4 });

      // Act & Assert
      expect(tx.nextVersion()).toBe(5);
    });
  });

  describe("bumpVersion", () => {
    // Happy path

    it("increments version by 1 and preserves other fields", () => {
      // Arrange
      const existing = fakeTransaction({ version: 4 });

      // Act
      const result = existing.bumpVersion();

      // Assert
      expect(result.toData()).toEqual({
        ...existing.toData(),
        version: 5,
      });
    });
  });

  describe("update", () => {
    beforeEach(() => {
      vi.useFakeTimers().setSystemTime(new Date("2000-01-02T10:11:12.000Z"));
    });

    afterEach(() => {
      vi.useRealTimers();
    });

    // Happy path

    it("sets amount", () => {
      // Arrange
      const existing = fakeTransaction({ amount: 10, categoryId: undefined });

      // Act
      const result = existing.update(
        { amount: 20 },
        { currentCategory: undefined },
      );

      // Assert
      expect(result.amount).toEqual(20);
    });

    it("sets type", () => {
      // Arrange
      const existing = fakeExpense({ categoryId: undefined });

      // Act
      const result = existing.update(
        { type: "INCOME" },
        { currentCategory: undefined },
      );

      // Assert
      expect(result.type).toBe(TransactionType.INCOME);
    });

    it("sets date", () => {
      // Arrange
      const existing = fakeTransaction({
        date: toDateString("2020-01-01"),
        categoryId: undefined,
      });

      // Act
      const result = existing.update(
        { date: toDateString("2021-06-15") },
        { currentCategory: undefined },
      );

      // Assert
      expect(result.date).toBe("2021-06-15");
    });

    it("keeps amount, type, and date when input is empty", () => {
      // Arrange
      const existing = fakeTransaction({ categoryId: undefined });

      // Act
      const result = existing.update({}, { currentCategory: undefined });

      // Assert
      expect(result.amount).toBe(existing.amount);
      expect(result.type).toBe(existing.type);
      expect(result.date).toBe(existing.date);
    });

    it("sets account and derives currency from new account", () => {
      // Arrange
      const userId = faker.string.uuid();
      const existing = fakeTransaction({
        userId,
        currency: "USD",
        categoryId: undefined,
      });
      const newAccount = fakeAccount({ userId, currency: "EUR" });

      // Act
      const result = existing.update(
        { account: newAccount },
        { currentCategory: undefined },
      );

      // Assert
      expect(result.accountId).toBe(newAccount.id);
      expect(result.currency).toBe("EUR");
    });

    it("keeps account and currency when input is undefined", () => {
      // Arrange
      const existing = fakeTransaction({
        currency: "GBP",
        categoryId: undefined,
      });

      // Act
      const result = existing.update(
        { account: undefined, amount: 1 },
        { currentCategory: undefined },
      );

      // Assert
      expect(result.accountId).toBe(existing.accountId);
      expect(result.currency).toBe("GBP");
    });

    it("sets category", () => {
      // Arrange
      const userId = faker.string.uuid();
      const existing = fakeTransaction({ userId, categoryId: undefined });
      const newCategory = fakeCategory({ userId, type: "EXPENSE" });

      // Act
      const result = existing.update(
        { category: newCategory },
        { currentCategory: undefined },
      );

      // Assert
      expect(result.categoryId).toBe(newCategory.id);
    });

    it("clears category when input is null", () => {
      // Arrange
      const currentCategory = fakeCategory();
      const existing = fakeTransaction({ categoryId: currentCategory.id });

      // Act
      const result = existing.update({ category: null }, { currentCategory });

      // Assert
      expect(result.categoryId).toBeUndefined();
    });

    it("keeps category when input is undefined", () => {
      // Arrange
      const currentCategory = fakeCategory();
      const existing = fakeTransaction({ categoryId: currentCategory.id });

      // Act
      const result = existing.update(
        { category: undefined, amount: 1 },
        { currentCategory },
      );

      // Assert
      expect(result.categoryId).toBe(currentCategory.id);
    });

    it("sets REFUND type and keeps EXPENSE category", () => {
      // Arrange
      const currentCategory = fakeCategory({ type: "EXPENSE" });
      const existing = fakeExpense({ categoryId: currentCategory.id });

      // Act
      const result = existing.update({ type: "REFUND" }, { currentCategory });

      // Assert
      expect(result.type).toBe(TransactionType.REFUND);
      expect(result.categoryId).toBe(currentCategory.id);
    });

    it("sets REFUND type and keeps archived EXPENSE category", () => {
      // Arrange
      const currentCategory = fakeCategory({
        type: "EXPENSE",
        isArchived: true,
      });
      const existing = fakeExpense({ categoryId: currentCategory.id });

      // Act
      const result = existing.update({ type: "REFUND" }, { currentCategory });

      // Assert
      expect(result.type).toBe(TransactionType.REFUND);
      expect(result.categoryId).toBe(currentCategory.id);
    });

    it("sets amount and keeps archived category", () => {
      // Arrange
      const currentCategory = fakeCategory({
        type: "EXPENSE",
        isArchived: true,
      });
      const existing = fakeExpense({ categoryId: currentCategory.id });

      // Act
      const result = existing.update({ amount: 20 }, { currentCategory });

      // Assert
      expect(result.amount).toBe(20);
      expect(result.categoryId).toBe(currentCategory.id);
    });

    it("sets INCOME type with new INCOME category in place of EXPENSE category", () => {
      // Arrange
      const userId = faker.string.uuid();
      const currentExpenseCategory = fakeCategory({ userId, type: "EXPENSE" });
      const newIncomeCategory = fakeCategory({ userId, type: "INCOME" });
      const existing = fakeExpense({
        userId,
        categoryId: currentExpenseCategory.id,
      });

      // Act
      const result = existing.update(
        { type: "INCOME", category: newIncomeCategory },
        { currentCategory: currentExpenseCategory },
      );

      // Assert
      expect(result.type).toBe(TransactionType.INCOME);
      expect(result.categoryId).toBe(newIncomeCategory.id);
    });

    it("sets INCOME type and clears EXPENSE category", () => {
      // Arrange
      const currentCategory = fakeCategory({ type: "EXPENSE" });
      const existing = fakeExpense({ categoryId: currentCategory.id });

      // Act
      const result = existing.update(
        { type: "INCOME", category: null },
        { currentCategory },
      );

      // Assert
      expect(result.type).toBe(TransactionType.INCOME);
      expect(result.categoryId).toBeUndefined();
    });

    it("trims description", () => {
      // Arrange
      const existing = fakeTransaction({
        description: "old",
        categoryId: undefined,
      });

      // Act
      const result = existing.update(
        { description: "  new  " },
        { currentCategory: undefined },
      );

      // Assert
      expect(result.description).toBe("new");
    });

    it("clears description when input is null", () => {
      // Arrange
      const existing = fakeTransaction({
        description: "old",
        categoryId: undefined,
      });

      // Act
      const result = existing.update(
        { description: null },
        { currentCategory: undefined },
      );

      // Assert
      expect(result.description).toBeUndefined();
    });

    it("keeps description when input is undefined", () => {
      // Arrange
      const existing = fakeTransaction({
        description: "keep me",
        categoryId: undefined,
      });

      // Act
      const result = existing.update(
        { description: undefined, amount: 1 },
        { currentCategory: undefined },
      );

      // Assert
      expect(result.description).toBe("keep me");
    });

    it("preserves id, userId, transferId, isArchived, createdAt", () => {
      // Arrange
      const existing = fakeTransferOut({
        id: "id-1",
        userId: "user-1",
        categoryId: undefined,
        transferId: "transfer-1",
        createdAt: toDateTimeString("1999-01-01T00:00:00.000Z"),
      });

      // Act
      const result = existing.update(
        { amount: 1 },
        { currentCategory: undefined },
      );

      // Assert
      expect(result.id).toBe("id-1");
      expect(result.userId).toBe("user-1");
      expect(result.transferId).toBe("transfer-1");
      expect(result.isArchived).toBe(false);
      expect(result.createdAt).toBe("1999-01-01T00:00:00.000Z");
    });

    it("sets updatedAt", () => {
      // Arrange
      const existing = fakeTransaction({ categoryId: undefined });

      // Act
      const result = existing.update(
        { amount: 1 },
        { currentCategory: undefined },
      );

      // Assert
      expect(result.updatedAt).toBe("2000-01-02T10:11:12.000Z");
    });

    // Validation failures

    it("throws on updating archived transaction", () => {
      // Arrange
      const existing = fakeTransaction({
        isArchived: true,
        categoryId: undefined,
      });

      // Act & Assert
      expect(() =>
        existing.update({ amount: 5 }, { currentCategory: undefined }),
      ).toThrow(new ModelError("Cannot update archived transaction"));
    });

    it("throws on zero amount", () => {
      // Arrange
      const existing = fakeTransaction({ categoryId: undefined });

      // Act & Assert
      expect(() =>
        existing.update({ amount: 0 }, { currentCategory: undefined }),
      ).toThrow(new ModelError("Amount must be positive"));
    });

    it("throws on negative amount", () => {
      // Arrange
      const existing = fakeTransaction({ categoryId: undefined });

      // Act & Assert
      expect(() =>
        existing.update({ amount: -1 }, { currentCategory: undefined }),
      ).toThrow(new ModelError("Amount must be positive"));
    });

    it("throws when account belongs to different user", () => {
      // Arrange
      const existing = fakeTransaction({
        userId: "user-a",
        categoryId: undefined,
      });
      const account = fakeAccount({ userId: "user-b" });

      // Act & Assert
      expect(() =>
        existing.update({ account }, { currentCategory: undefined }),
      ).toThrow(new ModelError("Account does not belong to user"));
    });

    it("throws on archived account", () => {
      // Arrange
      const userId = faker.string.uuid();
      const existing = fakeTransaction({ userId, categoryId: undefined });
      const account = fakeAccount({ userId, isArchived: true });

      // Act & Assert
      expect(() =>
        existing.update({ account }, { currentCategory: undefined }),
      ).toThrow(new ModelError("Account must not be archived"));
    });

    it("throws when category belongs to different user", () => {
      // Arrange
      const existing = fakeTransaction({
        userId: "user-a",
        categoryId: undefined,
      });
      const category = fakeCategory({
        userId: "user-b",
        type: "EXPENSE",
      });

      // Act & Assert
      expect(() =>
        existing.update({ category }, { currentCategory: undefined }),
      ).toThrow(new ModelError("Category does not belong to user"));
    });

    it("throws on archived category", () => {
      // Arrange
      const userId = faker.string.uuid();
      const existing = fakeTransaction({ userId, categoryId: undefined });
      const category = fakeCategory({
        userId,
        type: "EXPENSE",
        isArchived: true,
      });

      // Act & Assert
      expect(() =>
        existing.update({ category }, { currentCategory: undefined }),
      ).toThrow(new ModelError("Category must not be archived"));
    });

    it("throws on INCOME category for EXPENSE transaction", () => {
      // Arrange
      const userId = faker.string.uuid();
      const existing = fakeExpense({
        userId,
        categoryId: undefined,
      });
      const category = fakeCategory({ userId, type: "INCOME" });

      // Act & Assert
      expect(() =>
        existing.update({ category }, { currentCategory: undefined }),
      ).toThrow(
        new ModelError(
          'Category type "INCOME" does not match transaction type "EXPENSE"',
        ),
      );
    });

    it("fails when transaction has no category and current category is given", () => {
      // Arrange
      const existing = fakeExpense({ categoryId: undefined });
      const currentCategory = fakeCategory({ type: "EXPENSE" });

      // Act & Assert
      expect(() => existing.update({ amount: 1 }, { currentCategory })).toThrow(
        new ModelError("Current category does not match transaction category"),
      );
    });

    it("fails when transaction has category and current category is undefined", () => {
      // Arrange
      const existing = fakeExpense({ categoryId: faker.string.uuid() });

      // Act & Assert
      expect(() =>
        existing.update({ amount: 1 }, { currentCategory: undefined }),
      ).toThrow(
        new ModelError("Current category does not match transaction category"),
      );
    });

    it("fails when current category id differs from transaction category id", () => {
      // Arrange
      const existing = fakeExpense({ categoryId: faker.string.uuid() });
      const currentCategory = fakeCategory({ type: "EXPENSE" });

      // Act & Assert
      expect(() => existing.update({ amount: 1 }, { currentCategory })).toThrow(
        new ModelError("Current category does not match transaction category"),
      );
    });

    it("fails on INCOME type with kept EXPENSE category", () => {
      // Arrange
      const currentCategory = fakeCategory({ type: "EXPENSE" });
      const existing = fakeExpense({ categoryId: currentCategory.id });

      // Act & Assert
      expect(() =>
        existing.update({ type: "INCOME" }, { currentCategory }),
      ).toThrow(
        new ModelError(
          'Category type "EXPENSE" does not match transaction type "INCOME"',
        ),
      );
    });

    it("fails on INCOME type with kept archived EXPENSE category", () => {
      // Arrange
      const currentCategory = fakeCategory({
        type: "EXPENSE",
        isArchived: true,
      });
      const existing = fakeExpense({ categoryId: currentCategory.id });

      // Act & Assert
      expect(() =>
        existing.update({ type: "INCOME" }, { currentCategory }),
      ).toThrow(
        new ModelError(
          'Category type "EXPENSE" does not match transaction type "INCOME"',
        ),
      );
    });

    it("throws when setting category on transfer transaction", () => {
      // Arrange
      const userId = faker.string.uuid();
      const existing = fakeTransferOut({
        userId,
        categoryId: undefined,
        transferId: faker.string.uuid(),
      });
      const category = fakeCategory({ userId, type: "EXPENSE" });

      // Act & Assert
      expect(() =>
        existing.update({ category }, { currentCategory: undefined }),
      ).toThrow(new ModelError("Transfer transactions cannot have a category"));
    });

    it("throws when description exceeds maximum length", () => {
      // Arrange
      const existing = fakeTransaction({ categoryId: undefined });
      const tooLong = "x".repeat(DESCRIPTION_MAX_LENGTH + 1);

      // Act & Assert
      expect(() =>
        existing.update(
          { description: tooLong },
          { currentCategory: undefined },
        ),
      ).toThrow(
        new ModelError(
          `Description cannot exceed ${DESCRIPTION_MAX_LENGTH} characters`,
        ),
      );
    });

    it("throws on switching non-transfer to transfer type", () => {
      // Arrange
      const existing = fakeExpense({
        categoryId: undefined,
        transferId: undefined,
      });

      // Act & Assert
      expect(() =>
        existing.update(
          { type: "TRANSFER_OUT" },
          { currentCategory: undefined },
        ),
      ).toThrow(
        new ModelError("Transfer transactions must include transferId"),
      );
    });

    it("throws when switching to transfer type without clearing category", () => {
      // Arrange — existing transaction has categoryId; switching type to
      // transfer surfaces category invariant first
      const currentCategory = fakeCategory();
      const existing = fakeExpense({ categoryId: currentCategory.id });

      // Act & Assert
      expect(() =>
        existing.update({ type: "TRANSFER_OUT" }, { currentCategory }),
      ).toThrow(new ModelError("Transfer transactions cannot have a category"));
    });

    it("throws on switching transfer to non-transfer type", () => {
      // Arrange
      const existing = fakeTransferOut({
        categoryId: undefined,
        transferId: faker.string.uuid(),
      });

      // Act & Assert
      expect(() =>
        existing.update({ type: "EXPENSE" }, { currentCategory: undefined }),
      ).toThrow(
        new ModelError("Only transfer transactions can include transferId"),
      );
    });
  });

  describe("archive", () => {
    beforeEach(() => {
      vi.useFakeTimers().setSystemTime(new Date("2000-01-02T10:11:12.000Z"));
    });

    afterEach(() => {
      vi.useRealTimers();
    });

    // Happy path

    it("sets isArchived to true", () => {
      // Arrange
      const existing = fakeTransaction();

      // Act
      const result = existing.archive();

      // Assert
      expect(result.isArchived).toBe(true);
    });

    it("sets updatedAt", () => {
      // Arrange
      const existing = fakeTransaction();

      // Act
      const result = existing.archive();

      // Assert
      expect(result.updatedAt).toBe("2000-01-02T10:11:12.000Z");
    });

    // Validation failures

    it("throws on already archived transaction", () => {
      // Arrange
      const existing = fakeTransaction({ isArchived: true });

      // Act & Assert
      expect(() => existing.archive()).toThrow(
        new ModelError("Cannot archive archived transaction"),
      );
    });
  });
});

