      expect(mockAtomicWriter.commit).not.toHaveBeenCalled();
    });

    it("rejects duplicate categoryIds across legs", async () => {
      // Arrange
      const input = fakeCreateCompoundTransactionServiceInput({
        legs: [
          {
            amount: 10,
            categoryId: "same-category",
          },
          {
            amount: 5,
            categoryId: "same-category",
          },
        ],
      });

      // Act
      const result = await service.createCompoundTransaction(input, userId);

      // Assert
      expect(result).toBeFailure(
        "Compound transaction legs must have distinct categories, with at most one uncategorized leg",
      );
      expect(mockAtomicWriter.commit).not.toHaveBeenCalled();
    });

    it("rejects more than one uncategorized leg", async () => {
      // Arrange
      const input = fakeCreateCompoundTransactionServiceInput({
        legs: [{ amount: 10 }, { amount: 5 }],
      });

      // Act
      const result = await service.createCompoundTransaction(input, userId);

      // Assert
      expect(result).toBeFailure(
        "Compound transaction legs must have distinct categories, with at most one uncategorized leg",
      );
      expect(mockAtomicWriter.commit).not.toHaveBeenCalled();
    });

    it("fails when account not found", async () => {
      // Arrange
      const input = fakeCreateCompoundTransactionServiceInput();

      // Returns no account
      mockAccountRepository.findOneById.mockResolvedValue(null);

      // Act
      const result = await service.createCompoundTransaction(input, userId);

      // Assert
      expect(result).toBeFailure("Account not found or doesn't belong to user");
      expect(mockAtomicWriter.commit).not.toHaveBeenCalled();
    });

    it("fails when category not found", async () => {
      // Arrange
      const account = fakeAccount({ userId });
      const categoryA = fakeCategory({ userId, type: "EXPENSE" });
      const input = fakeCreateCompoundTransactionServiceInput({
        accountId: account.id,
        type: "EXPENSE",
        legs: [
          {
            amount: 10,
            categoryId: categoryA.id,
          },
          {
            amount: 5,
            categoryId: faker.string.uuid(),
          },
        ],
      });

      // Returns account owned by user
      mockAccountRepository.findOneById.mockResolvedValue(account);

      // Returns no category for one leg
      mockCategoryRepository.findOneById
        .mockResolvedValueOnce(categoryA)
        .mockResolvedValueOnce(null);

      // Act
      const result = await service.createCompoundTransaction(input, userId);

      // Assert
      expect(result).toBeFailure(
        "Category not found or doesn't belong to user",
      );
      expect(mockAtomicWriter.commit).not.toHaveBeenCalled();
    });

    it("fails when category type does not match transaction type", async () => {
      // Arrange
      const account = fakeAccount({ userId });
      const validCategory = fakeCategory({ userId, type: "EXPENSE" });
      const wrongCategory = fakeCategory({ userId, type: "INCOME" });
      const input = fakeCreateCompoundTransactionServiceInput({
        accountId: account.id,
        type: "EXPENSE",
        legs: [
          {
            amount: 10,
            categoryId: validCategory.id,
          },
          {
            amount: 5,
            categoryId: wrongCategory.id,
          },
        ],
      });

      // Returns account owned by user
      mockAccountRepository.findOneById.mockResolvedValue(account);

      // Returns categories with mismatched type
      mockCategoryRepository.findOneById
        .mockResolvedValueOnce(validCategory)
        .mockResolvedValueOnce(wrongCategory);

      // Act
      const result = await service.createCompoundTransaction(input, userId);

      // Assert
      expect(result).toBeFailure(
        'Category type "INCOME" does not match transaction type "EXPENSE"',
      );
      expect(mockAtomicWriter.commit).not.toHaveBeenCalled();
    });

    it("fails when model invariant is violated", async () => {
      // Arrange
      const account = fakeAccount({ userId });
      const categoryA = fakeCategory({ userId, type: "EXPENSE" });
      const categoryB = fakeCategory({ userId, type: "EXPENSE" });

      // Negative leg amount triggers ModelError, which the service must expose as failure
      const input = fakeCreateCompoundTransactionServiceInput({
        accountId: account.id,
        type: "EXPENSE",
        legs: [
          {
            amount: 10,
            categoryId: categoryA.id,
          },
          {
            amount: -5,
            categoryId: categoryB.id,
          },
        ],
      });

      // Returns account owned by user
      mockAccountRepository.findOneById.mockResolvedValue(account);

      // Returns each leg's category owned by user, in leg order
      mockCategoryRepository.findOneById
        .mockResolvedValueOnce(categoryA)
        .mockResolvedValueOnce(categoryB);

      // Act
      const result = await service.createCompoundTransaction(input, userId);

      // Assert
      expect(result).toBeFailure("Amount must be positive");
      expect(mockAtomicWriter.commit).not.toHaveBeenCalled();
    });
  });

  describe("updateTransaction", () => {
    // Happy path

    it("returns persisted transaction", async () => {
      // Arrange
      const currentCategory = fakeCategory({ userId, type: "INCOME" });
      const existingTransaction = fakeIncome({
        userId,
        categoryId: currentCategory.id,
      });
      const existingAccount = fakeAccount({
        userId,
        id: existingTransaction.accountId,
      });
      const newAccount = fakeAccount({ userId });
      const newCategory = fakeCategory({ userId, type: "EXPENSE" });
      const persistedTransaction = fakeTransaction();
      // Returns existing transaction
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );
      // Returns current category
      mockCategoryRepository.findOneWithArchivedById.mockResolvedValue(
        currentCategory,
      );
      // Returns new account owned by user
      mockAccountRepository.findOneById.mockResolvedValue(newAccount);
      // Returns existing account
      mockAccountRepository.findOneWithArchivedById.mockResolvedValue(
        existingAccount,
      );
      // Returns new category owned by user
      mockCategoryRepository.findOneById.mockResolvedValue(newCategory);
      // Persists and returns transaction
      mockAtomicWriter.commit.mockResolvedValue({
        createdTransactions: [],
        updatedTransactions: [persistedTransaction],
        updatedAccounts: [],
      });

      // Act
      const result = await service.updateTransaction(
        existingTransaction.id,
        userId,
        {
          accountId: newAccount.id,
          amount: 200,
          categoryId: newCategory.id,
          date: toDateString("2000-12-31"),
          description: "Updated transaction",
          type: "EXPENSE",
        },
      );

      // Assert
      expect(result).toBeSuccess(persistedTransaction);
      const commitInput = mockAtomicWriter.commit.mock.calls[0]?.[0];
      expect(commitInput?.transactionsToUpdate).toHaveLength(1);
      expect(commitInput?.transactionsToUpdate?.[0]).toMatchObject({
        accountId: newAccount.id,
        amount: 200,
        categoryId: newCategory.id,
        currency: newAccount.currency,
        date: toDateString("2000-12-31"),
        description: "Updated transaction",
        id: existingTransaction.id,
        type: TransactionType.EXPENSE,
        userId,
      });
    });

    it("preserves account when accountId is omitted", async () => {
      // Arrange
      const currentCategory = fakeCategory({ userId, type: "EXPENSE" });
      const existingTransaction = fakeExpense({
        userId,
        categoryId: currentCategory.id,
      });
      const existingAccount = fakeAccount({
        userId,
        id: existingTransaction.accountId,
      });
      // Returns existing transaction
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );
      // Returns current category
      mockCategoryRepository.findOneWithArchivedById.mockResolvedValue(
        currentCategory,
      );
      // Returns existing account
      mockAccountRepository.findOneWithArchivedById.mockResolvedValue(
        existingAccount,
      );
      // Persists and returns transaction
      mockAtomicWriter.commit.mockResolvedValue({
        createdTransactions: [],
        updatedTransactions: [fakeTransaction()],
        updatedAccounts: [],
      });

      // Act
      await service.updateTransaction(existingTransaction.id, userId, {
        amount: 5,
      });

      // Assert
      const commitInput = mockAtomicWriter.commit.mock.calls[0]?.[0];
      expect(commitInput?.transactionsToUpdate?.[0]?.accountId).toBe(
        existingTransaction.accountId,
      );
      expect(commitInput?.transactionsToUpdate?.[0]?.amount).toBe(5);
    });

    it("clears category when categoryId is null", async () => {
      // Arrange
      const currentCategory = fakeCategory({ userId, type: "EXPENSE" });
      const existingTransaction = fakeExpense({
        userId,
        categoryId: currentCategory.id,
      });
      // Returns existing transaction
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );
      // Returns current category
      mockCategoryRepository.findOneWithArchivedById.mockResolvedValue(
        currentCategory,
      );
      // Persists and returns transaction
      mockAtomicWriter.commit.mockResolvedValue({
        createdTransactions: [],
        updatedTransactions: [fakeTransaction()],
        updatedAccounts: [],
      });

      // Act
      await service.updateTransaction(existingTransaction.id, userId, {
        categoryId: null,
      });

      // Assert
      const commitInput = mockAtomicWriter.commit.mock.calls[0]?.[0];
      expect(
        commitInput?.transactionsToUpdate?.[0]?.categoryId,
      ).toBeUndefined();
    });

    it("skips account update when balance is unaffected", async () => {
      // Arrange
      const currentCategory = fakeCategory({ userId, type: "INCOME" });
      const existingTransaction = fakeIncome({
        userId,
        categoryId: currentCategory.id,
        amount: 10,
      });
      // Returns existing transaction
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );
      // Returns current category
      mockCategoryRepository.findOneWithArchivedById.mockResolvedValue(
        currentCategory,
      );
      // Persists and returns transaction
      mockAtomicWriter.commit.mockResolvedValue({
        createdTransactions: [],
        updatedTransactions: [fakeTransaction()],
        updatedAccounts: [],
      });

      // Act
      await service.updateTransaction(existingTransaction.id, userId, {
        description: "new note",
      });

      // Assert
      const commitInput = mockAtomicWriter.commit.mock.calls[0]?.[0];
      expect(commitInput?.accountsToUpdate).toEqual([]);
    });

    it("updates balance when amount changes on same account", async () => {
      // Arrange
      const existingAccount = fakeAccount({ userId, transactionBalance: 100 });
      const currentCategory = fakeCategory({ userId, type: "EXPENSE" });
      const existingTransaction = fakeExpense({
        accountId: existingAccount.id,
        userId,
        categoryId: currentCategory.id,
        amount: 30,
      });
      // Returns existing transaction
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );
      // Returns current category
      mockCategoryRepository.findOneWithArchivedById.mockResolvedValue(
        currentCategory,
      );
      // Returns existing account
      mockAccountRepository.findOneWithArchivedById.mockResolvedValue(
        existingAccount,
      );
      // Persists and returns transaction
      mockAtomicWriter.commit.mockResolvedValue({
        createdTransactions: [],
        updatedTransactions: [fakeTransaction()],
        updatedAccounts: [],
      });

      // Act
      await service.updateTransaction(existingTransaction.id, userId, {
        amount: 50,
      });

      // Assert
      const commitInput = mockAtomicWriter.commit.mock.calls[0]?.[0];
      // 100 + 30 (revert -30) - 50 (apply -50) = 80
      expect(commitInput?.accountsToUpdate).toHaveLength(1);
      expect(commitInput?.accountsToUpdate?.[0]?.transactionBalance).toBe(80);
    });

    it("updates both accounts when account changes", async () => {
      // Arrange
      const existingAccount = fakeAccount({ userId, transactionBalance: 100 });
      const newAccount = fakeAccount({ userId, transactionBalance: 0 });
      const currentCategory = fakeCategory({ userId, type: "EXPENSE" });
      const existingTransaction = fakeExpense({
        accountId: existingAccount.id,
        userId,
        categoryId: currentCategory.id,
        amount: 30,
      });
      // Returns existing transaction
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );
      // Returns current category
      mockCategoryRepository.findOneWithArchivedById.mockResolvedValue(
        currentCategory,
      );
      // Returns new account owned by user
      mockAccountRepository.findOneById.mockResolvedValue(newAccount);
      // Returns existing account
      mockAccountRepository.findOneWithArchivedById.mockResolvedValue(
        existingAccount,
      );
      // Persists and returns transaction
      mockAtomicWriter.commit.mockResolvedValue({
        createdTransactions: [],
        updatedTransactions: [fakeTransaction()],
        updatedAccounts: [],
      });

      // Act
      await service.updateTransaction(existingTransaction.id, userId, {
        accountId: newAccount.id,
      });

      // Assert
      const commitInput = mockAtomicWriter.commit.mock.calls[0]?.[0];
      expect(commitInput?.accountsToUpdate).toHaveLength(2);
      // existing: 100 + 30 (revert -30) = 130
      expect(
        commitInput?.accountsToUpdate?.find((a) => a.id === existingAccount.id)
          ?.transactionBalance,
      ).toBe(130);
      // new: 0 + (-30) = -30
      expect(
        commitInput?.accountsToUpdate?.find((a) => a.id === newAccount.id)
          ?.transactionBalance,
      ).toBe(-30);
    });

    it("updates balance when type changes", async () => {
      // Arrange
      const existingAccount = fakeAccount({ userId, transactionBalance: 100 });
      const existingTransaction = fakeExpense({
        accountId: existingAccount.id,
        userId,
        categoryId: undefined,
        amount: 20,
      });
      // Returns existing transaction
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );
      // Returns existing account
      mockAccountRepository.findOneWithArchivedById.mockResolvedValue(
        existingAccount,
      );
      // Persists and returns transaction
      mockAtomicWriter.commit.mockResolvedValue({
        createdTransactions: [],
        updatedTransactions: [fakeTransaction()],
        updatedAccounts: [],
      });

      // Act
      await service.updateTransaction(existingTransaction.id, userId, {
        type: "INCOME",
      });

      // Assert
      const commitInput = mockAtomicWriter.commit.mock.calls[0]?.[0];
      // 100 + 20 (revert -20) + 20 (apply +20) = 140
      expect(commitInput?.accountsToUpdate).toHaveLength(1);
      expect(commitInput?.accountsToUpdate?.[0]?.transactionBalance).toBe(140);
    });

    it("loads current transaction category", async () => {
      // Arrange
      const currentCategory = fakeCategory({ userId, type: "EXPENSE" });
      const existingTransaction = fakeExpense({
        userId,
        categoryId: currentCategory.id,
      });
      // Returns existing transaction
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );
      // Returns current category
      mockCategoryRepository.findOneWithArchivedById.mockResolvedValue(
        currentCategory,
      );
      // Persists and returns transaction
      mockAtomicWriter.commit.mockResolvedValue({
        createdTransactions: [],
        updatedTransactions: [fakeTransaction()],
        updatedAccounts: [],
      });

      // Act
      const result = await service.updateTransaction(
        existingTransaction.id,
        userId,
        { description: "new note" },
      );

      // Assert
      expect(result.success).toBe(true);
      expect(
        mockCategoryRepository.findOneWithArchivedById,
      ).toHaveBeenCalledWith({ id: currentCategory.id, userId });
    });

    it("skips current category lookup when transaction has no category", async () => {
      // Arrange
      const existingTransaction = fakeExpense({
        userId,
        categoryId: undefined,
      });
      // Returns existing transaction
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );
      // Persists and returns transaction
      mockAtomicWriter.commit.mockResolvedValue({
        createdTransactions: [],
        updatedTransactions: [fakeTransaction()],
        updatedAccounts: [],
      });

      // Act
      const result = await service.updateTransaction(
        existingTransaction.id,
        userId,
        { description: "new note" },
      );

      // Assert
      expect(result.success).toBe(true);
      expect(
        mockCategoryRepository.findOneWithArchivedById,
      ).not.toHaveBeenCalled();
    });

    // Validation failures

    it("fails when transaction not found", async () => {
      // Arrange
      // Returns no transaction
      mockTransactionRepository.findOneById.mockResolvedValue(null);

      // Act
      const result = await service.updateTransaction(
        faker.string.uuid(),
        userId,
        { amount: 1 },
      );

      // Assert
      expect(result).toBeFailure(
        "Transaction not found or doesn't belong to user",
      );
      expect(mockAtomicWriter.commit).not.toHaveBeenCalled();
    });

    it("fails when transaction belongs to transfer", async () => {
      // Arrange
      const existingTransaction = fakeTransferOut({ userId });
      // Returns transfer leg
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );

      // Act
      const result = await service.updateTransaction(
        existingTransaction.id,
        userId,
        { amount: 1 },
      );

      // Assert
      expect(result).toBeFailure(
        "Transfer transactions can only be edited as a transfer",
      );
      expect(mockAtomicWriter.commit).not.toHaveBeenCalled();
    });

    it("fails when account not found", async () => {
      // Arrange
      const currentCategory = fakeCategory({ userId, type: "EXPENSE" });
      const existingTransaction = fakeExpense({
        userId,
        categoryId: currentCategory.id,
      });
      // Returns existing transaction
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );
      // Returns current category
      mockCategoryRepository.findOneWithArchivedById.mockResolvedValue(
        currentCategory,
      );
      // Returns no account
      mockAccountRepository.findOneById.mockResolvedValue(null);

      // Act
      const result = await service.updateTransaction(
        existingTransaction.id,
        userId,
        { accountId: faker.string.uuid() },
      );

      // Assert
      expect(result).toBeFailure("Account not found or doesn't belong to user");
      expect(mockAtomicWriter.commit).not.toHaveBeenCalled();
    });

    it("fails when category type does not match transaction type", async () => {
      // Arrange
      const currentCategory = fakeCategory({ userId, type: "EXPENSE" });
      const existingTransaction = fakeExpense({
        userId,
        categoryId: currentCategory.id,
      });
      const newCategory = fakeCategory({ userId, type: "INCOME" });
      // Returns existing transaction
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );
      // Returns current category
      mockCategoryRepository.findOneWithArchivedById.mockResolvedValue(
        currentCategory,
      );
      // Returns category with mismatched type
      mockCategoryRepository.findOneById.mockResolvedValue(newCategory);

      // Act
      const result = await service.updateTransaction(
        existingTransaction.id,
        userId,
        { categoryId: newCategory.id },
      );

      // Assert
      expect(result).toBeFailure(
        'Category type "INCOME" does not match transaction type "EXPENSE"',
      );
      expect(mockAtomicWriter.commit).not.toHaveBeenCalled();
    });

    it("fails when current category not found", async () => {
      // Arrange
      const existingTransaction = fakeExpense({
        userId,
        categoryId: faker.string.uuid(),
      });
      // Returns existing transaction
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );
      // Returns no current category
      mockCategoryRepository.findOneWithArchivedById.mockResolvedValue(null);

      // Act
      const result = await service.updateTransaction(
        existingTransaction.id,
        userId,
        { amount: 1 },
      );

      // Assert
      expect(result).toBeFailure("Current category not found");
      expect(mockAtomicWriter.commit).not.toHaveBeenCalled();
    });

    it("fails when model invariant is violated", async () => {
      // Arrange
      const currentCategory = fakeCategory({ userId, type: "EXPENSE" });
      const existingTransaction = fakeExpense({
        userId,
        categoryId: currentCategory.id,
      });
      // Returns existing transaction
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );
      // Returns current category
      mockCategoryRepository.findOneWithArchivedById.mockResolvedValue(
        currentCategory,
      );
      // Negative amount triggers ModelError, which the service must expose as failure
      const input = { amount: -1 };

      // Act
      const result = await service.updateTransaction(
        existingTransaction.id,
        userId,
        input,
      );

      // Assert
      expect(result).toBeFailure("Amount must be positive");
      expect(mockAtomicWriter.commit).not.toHaveBeenCalled();
    });
  });

  describe("deleteTransaction", () => {
    // Happy path

    it("returns persisted archived transaction", async () => {
      // Arrange
      const existingTransaction = fakeTransaction({ userId });
      const existingAccount = fakeAccount({
        userId,
        id: existingTransaction.accountId,
      });
      const persistedTransaction = fakeTransaction({ isArchived: true });
      // Returns existing transaction
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );
      // Returns existing account
      mockAccountRepository.findOneWithArchivedById.mockResolvedValue(
        existingAccount,
      );
      // Persists and returns archived transaction
      mockAtomicWriter.commit.mockResolvedValue({
        createdTransactions: [],
        updatedTransactions: [persistedTransaction],
        updatedAccounts: [],
      });

      // Act
      const result = await service.deleteTransaction(
        existingTransaction.id,
        userId,
      );

      // Assert
      expect(result).toBeSuccess(persistedTransaction);
      const commitInput = mockAtomicWriter.commit.mock.calls[0]?.[0];
      expect(commitInput?.transactionsToUpdate).toHaveLength(1);
      expect(commitInput?.transactionsToUpdate?.[0]?.isArchived).toBe(true);
    });

    it("decreases account balance", async () => {
      // Arrange
      const existingAccount = fakeAccount({ userId, transactionBalance: 100 });
      const existingTransaction = fakeExpense({
        accountId: existingAccount.id,
        userId,
        amount: 30,
      });
      // Returns existing transaction
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );
      // Returns existing account
      mockAccountRepository.findOneWithArchivedById.mockResolvedValue(
        existingAccount,
      );
      // Persists and returns archived transaction
      mockAtomicWriter.commit.mockResolvedValue({
        createdTransactions: [],
        updatedTransactions: [fakeTransaction()],
        updatedAccounts: [],
      });

      // Act
      await service.deleteTransaction(existingTransaction.id, userId);

      // Assert
      const commitInput = mockAtomicWriter.commit.mock.calls[0]?.[0];
      // 100 + 30 (revert -30) = 130
      expect(commitInput?.accountsToUpdate).toHaveLength(1);
      expect(commitInput?.accountsToUpdate?.[0]?.transactionBalance).toBe(130);
    });

    it("returns existing transaction without commit when already archived", async () => {
      // Arrange
      const existingTransaction = fakeTransaction({ userId, isArchived: true });
      // Returns archived transaction
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );

      // Act
      const result = await service.deleteTransaction(
        existingTransaction.id,
        userId,
      );

      // Assert
      expect(result).toBeSuccess(existingTransaction);
      expect(mockAtomicWriter.commit).not.toHaveBeenCalled();
    });

    // Validation failures

    it("fails when transaction not found", async () => {
      // Arrange
      // Returns no transaction
      mockTransactionRepository.findOneById.mockResolvedValue(null);

      // Act
      const result = await service.deleteTransaction(
        faker.string.uuid(),
        userId,
      );

      // Assert
      expect(result).toBeFailure(
        "Transaction not found or doesn't belong to user",
      );
      expect(mockAtomicWriter.commit).not.toHaveBeenCalled();
    });

    it("fails when active transaction belongs to transfer", async () => {
      // Arrange
      const existingTransaction = fakeTransferOut({
        userId,
        isArchived: false,
      });
      // Returns active transfer leg
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );

      // Act
      const result = await service.deleteTransaction(
        existingTransaction.id,
        userId,
      );

      // Assert
      expect(result).toBeFailure(
        "Transfer transactions can only be deleted as a transfer",
      );
      expect(mockAtomicWriter.commit).not.toHaveBeenCalled();
    });

    it("fails when archived transaction belongs to transfer", async () => {
      // Arrange
      const existingTransaction = fakeTransferOut({ userId, isArchived: true });
      // Returns archived transfer leg
      mockTransactionRepository.findOneById.mockResolvedValue(
        existingTransaction,
      );

      // Act
      const result = await service.deleteTransaction(
        existingTransaction.id,
        userId,
      );

      // Assert
      expect(result).toBeFailure(
        "Transfer transactions can only be deleted as a transfer",
      );
      expect(mockAtomicWriter.commit).not.toHaveBeenCalled();
    });
  });
});

