import { faker } from "@faker-js/faker";
import { type Mocked, beforeEach, describe, expect, it } from "vitest";
import { NAME_MAX_LENGTH, NAME_MIN_LENGTH } from "../models/account";
import { AccountRepository } from "../ports/account-repository";
import { TransactionRepository } from "../ports/transaction-repository";
import {
  fakeAccount,
  fakeCreateAccountInput,
} from "../utils/test-utils/models/account-fakes";
import { createMockAccountRepository } from "../utils/test-utils/repositories/account-repository-mocks";
import { createMockTransactionRepository } from "../utils/test-utils/repositories/transaction-repository-mocks";
import { AccountServiceImpl } from "./account-service";

describe("AccountService", () => {
  let mockAccountRepository: Mocked<AccountRepository>;
  let mockTransactionRepository: Mocked<TransactionRepository>;
  let service: AccountServiceImpl;
  let userId: string;

  beforeEach(() => {
    mockAccountRepository = createMockAccountRepository();
    mockTransactionRepository = createMockTransactionRepository();

    service = new AccountServiceImpl(
      mockAccountRepository,
      mockTransactionRepository,
    );
    userId = faker.string.uuid();
  });

  describe("getAccountsByUser", () => {
    // Happy path

    it("returns active accounts for user when scope is active", async () => {
      // Arrange
      const accounts = [fakeAccount(), fakeAccount()];
      mockAccountRepository.findManyByUserId.mockResolvedValue(accounts);

      // Act
      const result = await service.getAccountsByUser(userId, "ACTIVE");

      // Assert
      expect(result).toBeSuccess(accounts);
      expect(mockAccountRepository.findManyByUserId).toHaveBeenCalledWith(
        userId,
      );
    });

    it("returns both active and archived accounts when scope is all", async () => {
      // Arrange
      const accounts = [
        fakeAccount({ isArchived: true }),
        fakeAccount({ isArchived: false }),
      ];
      mockAccountRepository.findManyWithArchivedByUserId.mockResolvedValue(
        accounts,
      );

      // Act
      const result = await service.getAccountsByUser(userId, "ALL");

      // Assert
      expect(result).toBeSuccess(accounts);
      expect(
        mockAccountRepository.findManyWithArchivedByUserId,
      ).toHaveBeenCalledWith(userId);
    });

    it("returns only archived accounts when scope is archived", async () => {
      // Arrange
      const accounts = [
        fakeAccount({ isArchived: true }),
        fakeAccount({ isArchived: false }),
      ];
      mockAccountRepository.findManyWithArchivedByUserId.mockResolvedValue(
        accounts,
      );

      // Act
      const result = await service.getAccountsByUser(userId, "ARCHIVED");

      // Assert
      expect(result).toBeSuccess(
        accounts.filter((account) => account.isArchived),
      );
      expect(
        mockAccountRepository.findManyWithArchivedByUserId,
      ).toHaveBeenCalledWith(userId);
    });

    // Dependency failures

    it("propagates repository errors for active scope", async () => {
      // Arrange

      // Repository throws on DB error
      mockAccountRepository.findManyByUserId.mockRejectedValue(
        new Error("Database error"),
      );

      // Act & Assert
      await expect(service.getAccountsByUser(userId, "ACTIVE")).rejects.toThrow(
        "Database error",
      );
    });

    it("propagates repository errors for all/archived scope", async () => {
      // Arrange

      // Repository throws on DB error
      mockAccountRepository.findManyWithArchivedByUserId.mockRejectedValue(
        new Error("Database error"),
      );

      // Act & Assert
      await expect(service.getAccountsByUser(userId, "ALL")).rejects.toThrow(
        "Database error",
      );
    });
  });

  describe("createAccount", () => {
    // Happy path

    it("creates and returns new account", async () => {
      // Arrange
      const input = fakeCreateAccountInput({ userId });
      mockAccountRepository.findManyByUserId.mockResolvedValue([]);

      // Act
      const result = await service.createAccount(input);

      // Assert
      expect(result).toBeSuccess(
        expect.objectContaining({
          userId,
          name: input.name,
          currency: input.currency,
          initialBalance: input.initialBalance,
          isArchived: false,
          version: 0,
        }),
      );
      expect(mockAccountRepository.create).toHaveBeenCalledTimes(1);
      expect(mockAccountRepository.create).toHaveBeenCalledWith(
        expect.objectContaining({
          userId,
          name: input.name,
          currency: input.currency,
          initialBalance: input.initialBalance,
        }),
      );
    });

    // Validation failures

    it("fails when model invariant is violated", async () => {
      // Arrange
      // Empty name triggers ModelError, which the service must expose as failure
      const input = fakeCreateAccountInput({ userId, name: "" });

      // Act
      const result = await service.createAccount(input);

      // Assert
      expect(result).toBeFailure(
        `Account name must be between ${NAME_MIN_LENGTH} and ${NAME_MAX_LENGTH} characters`,
      );
      expect(mockAccountRepository.findManyByUserId).not.toHaveBeenCalled();
      expect(mockAccountRepository.create).not.toHaveBeenCalled();
    });

    it("fails when account name already exists (case-insensitive)", async () => {
      // Arrange
      // Another account with the same name exists (different casing)
      mockAccountRepository.findManyByUserId.mockResolvedValue([
        fakeAccount({ name: "SAVINGS" }),
      ]);
      const input = fakeCreateAccountInput({ userId, name: "savings" });

      // Act
      const result = await service.createAccount(input);

      // Assert
      expect(result).toBeFailure('Account "savings" already exists');
      expect(mockAccountRepository.create).not.toHaveBeenCalled();
    });

    // Dependency failures

    it("propagates repository errors on create", async () => {
      // Arrange
      const input = fakeCreateAccountInput({ userId });
      mockAccountRepository.findManyByUserId.mockResolvedValue([]);

      // Repository throws on DB error
      mockAccountRepository.create.mockRejectedValue(
        new Error("Database error"),
      );

      // Act & Assert
      await expect(service.createAccount(input)).rejects.toThrow(
        "Database error",
      );
    });
  });

  describe("updateAccount", () => {
    // Happy path

    it("returns updated account", async () => {
      // Arrange
      const accountId = faker.string.uuid();
      const existingAccount = fakeAccount({
        id: accountId,
        userId,
        name: "Original",
      });

      // Account exists
      mockAccountRepository.findOneById.mockResolvedValue(existingAccount);
      // No name conflicts
      mockAccountRepository.findManyByUserId.mockResolvedValue([
        existingAccount,
      ]);
      mockAccountRepository.update.mockImplementation(async (account) =>
        account.bumpVersion(),
      );

      // Act
      const result = await service.updateAccount(accountId, userId, {
        name: "New Name",
      });

      // Assert
      expect(result).toBeSuccess(
        expect.objectContaining({
          id: accountId,
          userId,
          name: "New Name",
        }),
      );
      expect(mockAccountRepository.update).toHaveBeenCalledWith(
        expect.objectContaining({ id: accountId, name: "New Name" }),
      );
    });

    it("allows keeping same account name", async () => {
      // Arrange
      const accountId = faker.string.uuid();
      const currentAccount = fakeAccount({
        id: accountId,
        userId,
        name: "Savings",
      });

      mockAccountRepository.findOneById.mockResolvedValue(currentAccount);
      mockAccountRepository.update.mockImplementation(async (account) =>
        account.bumpVersion(),
      );

      // Act
      const result = await service.updateAccount(accountId, userId, {
        name: "Savings",
      });

      // Assert
      expect(result).toBeSuccess(expect.objectContaining({ name: "Savings" }));
      expect(mockAccountRepository.update).toHaveBeenCalled();
      // No duplicate-name lookup when the name does not change
      expect(mockAccountRepository.findManyByUserId).not.toHaveBeenCalled();
    });

    it("allows currency change when account has no transactions", async () => {
      // Arrange
      const accountId = faker.string.uuid();
      const currentAccount = fakeAccount({
        id: accountId,
        userId,
        currency: "USD",
      });

      mockAccountRepository.findOneById.mockResolvedValue(currentAccount);
      // No transactions for this account
      mockTransactionRepository.hasTransactionsForAccount.mockResolvedValue(
        false,
      );
      mockAccountRepository.update.mockImplementation(async (account) =>
        account.bumpVersion(),
      );

      // Act
      const result = await service.updateAccount(accountId, userId, {
        currency: "EUR",
      });

      // Assert
      expect(result).toBeSuccess(expect.objectContaining({ currency: "EUR" }));
      expect(mockAccountRepository.update).toHaveBeenCalledWith(
        expect.objectContaining({ currency: "EUR" }),
      );
    });

    // Validation failures

    it("fails when account is not found", async () => {
      // Arrange
      const accountId = faker.string.uuid();

      // Account does not exist
      mockAccountRepository.findOneById.mockResolvedValue(null);

      // Act
      const result = await service.updateAccount(accountId, userId, {
        name: "Test",
      });

      // Assert
      expect(result).toBeFailure("Account not found");
      expect(mockAccountRepository.update).not.toHaveBeenCalled();
    });

    it("fails when model invariant is violated", async () => {
      // Arrange
      const accountId = faker.string.uuid();
      const currentAccount = fakeAccount({ id: accountId, userId });
      mockAccountRepository.findOneById.mockResolvedValue(currentAccount);
      // Empty name triggers ModelError, which the service must expose as failure
      const input = { name: "" };

      // Act
      const result = await service.updateAccount(accountId, userId, input);

      // Assert
      expect(result).toBeFailure(
        `Account name must be between ${NAME_MIN_LENGTH} and ${NAME_MAX_LENGTH} characters`,
      );
      expect(mockAccountRepository.update).not.toHaveBeenCalled();
    });

    it("fails when updating archived account", async () => {
      // Arrange
      const accountId = faker.string.uuid();
      const currentAccount = fakeAccount({
        id: accountId,
        userId,
        isArchived: true,
      });
      mockAccountRepository.findOneById.mockResolvedValue(currentAccount);

      // Act
      const result = await service.updateAccount(accountId, userId, {
        name: "New Name",
      });

      // Assert
      expect(result).toBeFailure("Cannot update archived account");
      expect(mockAccountRepository.update).not.toHaveBeenCalled();
    });

    it("fails when updated name already exists for another account", async () => {
      // Arrange
      const accountId = faker.string.uuid();
      const currentAccount = fakeAccount({
        id: accountId,
        userId,
        name: "Checking",
      });
      const anotherAccount = fakeAccount({ userId, name: "Savings" });

      mockAccountRepository.findOneById.mockResolvedValue(currentAccount);
      // Another account already has the name "Savings"
      mockAccountRepository.findManyByUserId.mockResolvedValue([
        currentAccount,
        anotherAccount,
      ]);

      // Act
      const result = await service.updateAccount(accountId, userId, {
        name: "Savings",
      });

      // Assert
      expect(result).toBeFailure('Account "Savings" already exists');
      expect(mockAccountRepository.update).not.toHaveBeenCalled();
    });

    it("fails when changing currency and account has existing transactions", async () => {
      // Arrange
      const accountId = faker.string.uuid();
      const currentAccount = fakeAccount({
        id: accountId,
        userId,
        currency: "USD",
      });

      mockAccountRepository.findOneById.mockResolvedValue(currentAccount);
      // Account has existing transactions — currency cannot be changed
      mockTransactionRepository.hasTransactionsForAccount.mockResolvedValue(
        true,
      );

      // Act
      const result = await service.updateAccount(accountId, userId, {
        currency: "EUR",
      });

      // Assert
      expect(result).toBeFailure(
        "Cannot change currency for account that has existing transactions. Please create a new account with the desired currency instead.",
      );
      expect(mockAccountRepository.update).not.toHaveBeenCalled();
    });

    // Dependency failures

    it("propagates repository errors on update", async () => {
      // Arrange
      const accountId = faker.string.uuid();
      const currentAccount = fakeAccount({ id: accountId, userId });

      mockAccountRepository.findOneById.mockResolvedValue(currentAccount);
      mockAccountRepository.findManyByUserId.mockResolvedValue([
        currentAccount,
      ]);

      // Repository throws on DB write error
      mockAccountRepository.update.mockRejectedValue(
        new Error("Database error"),
      );

      // Act & Assert
      await expect(
        service.updateAccount(accountId, userId, { name: "New Name" }),
      ).rejects.toThrow("Database error");
    });
  });

  describe("deleteAccount", () => {
    // Happy path

    it("returns archived account", async () => {
      // Arrange
      const accountId = faker.string.uuid();
      const currentAccount = fakeAccount({
        id: accountId,
        userId,
        isArchived: false,
      });

      mockAccountRepository.findOneById.mockResolvedValue(currentAccount);
      mockAccountRepository.update.mockImplementation(async (account) =>
        account.bumpVersion(),
      );

      // Act
      const result = await service.deleteAccount(accountId, userId);

      // Assert
      expect(result).toBeSuccess(expect.objectContaining({ isArchived: true }));
      expect(mockAccountRepository.update).toHaveBeenCalledWith(
        expect.objectContaining({ id: accountId, isArchived: true }),
      );
    });

    // Validation failures

    it("fails when account is not found", async () => {
      // Arrange
      const accountId = faker.string.uuid();

      mockAccountRepository.findOneById.mockResolvedValue(null);

      // Act
      const result = await service.deleteAccount(accountId, userId);

      // Assert
      expect(result).toBeFailure("Account not found");
      expect(mockAccountRepository.update).not.toHaveBeenCalled();
    });

    it("fails when account already archived", async () => {
      // Arrange
      const accountId = faker.string.uuid();
      const currentAccount = fakeAccount({
        id: accountId,
        userId,
        isArchived: true,
      });

      mockAccountRepository.findOneById.mockResolvedValue(currentAccount);

      // Act
      const result = await service.deleteAccount(accountId, userId);

      // Assert
      expect(result).toBeFailure("Cannot archive archived account");
      expect(mockAccountRepository.update).not.toHaveBeenCalled();
    });

    // Dependency failures

    it("propagates repository errors on update", async () => {
      // Arrange
      const accountId = faker.string.uuid();
      const currentAccount = fakeAccount({ id: accountId, userId });

      mockAccountRepository.findOneById.mockResolvedValue(currentAccount);
      // Repository throws on DB error
      mockAccountRepository.update.mockRejectedValue(
        new Error("Database error"),
      );

      // Act & Assert
      await expect(service.deleteAccount(accountId, userId)).rejects.toThrow(
        "Database error",
      );
    });
  });
});

