import { faker } from "@faker-js/faker";
import { type Mocked, beforeEach, describe, expect, it } from "vitest";
import { NAME_MAX_LENGTH, NAME_MIN_LENGTH } from "../models/category";
import { CategoryRepository } from "../ports/category-repository";
import { TransactionRepository } from "../ports/transaction-repository";
import {
  fakeCategory,
  fakeCreateCategoryInput,
} from "../utils/test-utils/models/category-fakes";
import { createMockCategoryRepository } from "../utils/test-utils/repositories/category-repository-mocks";
import { createMockTransactionRepository } from "../utils/test-utils/repositories/transaction-repository-mocks";
import { CategoryServiceImpl } from "./category-service";

describe("CategoryService", () => {
  let mockCategoryRepository: Mocked<CategoryRepository>;
  let mockTransactionRepository: Mocked<TransactionRepository>;
  let service: CategoryServiceImpl;
  let userId: string;

  beforeEach(() => {
    mockCategoryRepository = createMockCategoryRepository();
    mockTransactionRepository = createMockTransactionRepository();
    service = new CategoryServiceImpl(
      mockCategoryRepository,
      mockTransactionRepository,
    );
    userId = faker.string.uuid();

    // Default: no existing categories for duplicate-name lookup
    mockCategoryRepository.findManyByUserId.mockResolvedValue([]);
    // Default: no active transactions in category
    mockTransactionRepository.hasTransactionsForCategory.mockResolvedValue(
      false,
    );
  });

  describe("getCategoriesByUser", () => {
    // Happy path

    it("returns active categories when no type provided", async () => {
      // Arrange
      // Repository returns two categories
      const categories = [fakeCategory(), fakeCategory()];
      mockCategoryRepository.findManyByUserId.mockResolvedValue(categories);

      // Act
      const result = await service.getCategoriesByUser(userId, {
        scope: "ACTIVE",
      });

      // Assert
      expect(result).toBeSuccess(categories);
      expect(mockCategoryRepository.findManyByUserId).toHaveBeenCalledWith(
        userId,
        { type: undefined },
      );
    });

    it("returns active categories filtered by given type", async () => {
      // Arrange
      const type = "INCOME";
      // Repository returns two income categories
      const categories = [fakeCategory(), fakeCategory()];
      mockCategoryRepository.findManyByUserId.mockResolvedValue(categories);

      // Act
      const result = await service.getCategoriesByUser(userId, {
        scope: "ACTIVE",
        type,
      });

      // Assert
      expect(result).toBeSuccess(categories);
      expect(mockCategoryRepository.findManyByUserId).toHaveBeenCalledWith(
        userId,
        { type },
      );
    });

    it("returns both active and archived categories when scope is all", async () => {
      // Arrange
      const categories = [
        fakeCategory({ isArchived: true }),
        fakeCategory({ isArchived: false }),
      ];
      mockCategoryRepository.findManyWithArchivedByUserId.mockResolvedValue(
        categories,
      );

      // Act
      const result = await service.getCategoriesByUser(userId, {
        scope: "ALL",
      });

      // Assert
      expect(result).toBeSuccess(categories);
      expect(
        mockCategoryRepository.findManyWithArchivedByUserId,
      ).toHaveBeenCalledWith(userId);
    });

    it("returns only archived categories when scope is archived", async () => {
      // Arrange
      const categories = [
        fakeCategory({ isArchived: true }),
        fakeCategory({ isArchived: false }),
      ];
      mockCategoryRepository.findManyWithArchivedByUserId.mockResolvedValue(
        categories,
      );

      // Act
      const result = await service.getCategoriesByUser(userId, {
        scope: "ARCHIVED",
      });

      // Assert
      expect(result).toBeSuccess(
        categories.filter((category) => category.isArchived),
      );
      expect(
        mockCategoryRepository.findManyWithArchivedByUserId,
      ).toHaveBeenCalledWith(userId);
    });

    it("filters by type when scope is all", async () => {
      // Arrange
      const matchingType = "INCOME";
      const categories = [
        fakeCategory({ type: matchingType, isArchived: true }),
        fakeCategory({ type: "EXPENSE", isArchived: false }),
      ];
      mockCategoryRepository.findManyWithArchivedByUserId.mockResolvedValue(
        categories,
      );

      // Act
      const result = await service.getCategoriesByUser(userId, {
        scope: "ALL",
        type: matchingType,
      });

      // Assert
      expect(result).toBeSuccess(categories.slice(0, 1)); // Only the first category
    });
  });

  describe("createCategory", () => {
    // Happy path

    it("creates and returns new category", async () => {
      // Arrange
      const input = fakeCreateCategoryInput({ userId });

      // Act
      const result = await service.createCategory(input);

      // Assert
      expect(result).toBeSuccess(
        expect.objectContaining({
          userId,
          name: input.name,
          type: input.type,
          excludeFromReports: input.excludeFromReports,
          isArchived: false,
        }),
      );
      expect(mockCategoryRepository.create).toHaveBeenCalledTimes(1);
      expect(mockCategoryRepository.create).toHaveBeenCalledWith(
        expect.objectContaining({
          userId,
          name: input.name,
          type: input.type,
          excludeFromReports: input.excludeFromReports,
          isArchived: false,
        }),
      );
    });

    it("trims name before persisting", async () => {
      // Arrange
      const input = fakeCreateCategoryInput({ name: "  Groceries  " });

      // Act
      await service.createCategory(input);

      // Assert
      expect(mockCategoryRepository.create).toHaveBeenCalledWith(
        expect.objectContaining({ name: "Groceries" }),
      );
    });

    // Validation failures

    it("fails when model invariant is violated", async () => {
      // Arrange
      // Empty name triggers ModelError, which the service must expose as failure
      const input = fakeCreateCategoryInput({ name: "" });

      // Act
      const result = await service.createCategory(input);

      // Assert
      expect(result).toBeFailure(
        `Category name must be between ${NAME_MIN_LENGTH} and ${NAME_MAX_LENGTH} characters`,
      );
      expect(mockCategoryRepository.create).not.toHaveBeenCalled();
    });

    it("fails when name matches existing category case-insensitively", async () => {
      // Arrange
      // Existing category uses same name in different casing
      mockCategoryRepository.findManyByUserId.mockResolvedValue([
        fakeCategory({ userId, name: "GROCERIES" }),
      ]);
      const input = fakeCreateCategoryInput({ userId, name: "groceries" });

      // Act
      const result = await service.createCategory(input);

      // Assert
      expect(result).toBeFailure('Category "groceries" already exists');
      expect(mockCategoryRepository.create).not.toHaveBeenCalled();
    });
  });

  describe("updateCategory", () => {
    // Happy path

    it("returns updated category", async () => {
      // Arrange
      const categoryId = faker.string.uuid();
      const existingCategory = fakeCategory({
        id: categoryId,
        userId,
        name: "Original",
        type: "EXPENSE",
      });

      mockCategoryRepository.findOneById.mockResolvedValue(existingCategory);
      mockCategoryRepository.update.mockImplementation(async (category) =>
        category.bumpVersion(),
      );

      // Act
      const result = await service.updateCategory(categoryId, userId, {
        name: "New Name",
        type: "INCOME",
      });

      // Assert
      expect(result).toBeSuccess(
        expect.objectContaining({
          id: categoryId,
          userId,
          name: "New Name",
          type: "INCOME",
        }),
      );
      expect(mockCategoryRepository.update).toHaveBeenCalledWith(
        expect.objectContaining({
          id: categoryId,
          name: "New Name",
          type: "INCOME",
        }),
      );
    });

    it("trims name before persisting", async () => {
      // Arrange
      const categoryId = faker.string.uuid();
      const existingCategory = fakeCategory({ id: categoryId, userId });

      mockCategoryRepository.findOneById.mockResolvedValue(existingCategory);
      mockCategoryRepository.update.mockImplementation(async (category) =>
        category.bumpVersion(),
      );

      // Act
      await service.updateCategory(categoryId, userId, {
        name: "  Groceries  ",
      });

      // Assert
      expect(mockCategoryRepository.update).toHaveBeenCalledWith(
        expect.objectContaining({ name: "Groceries" }),
      );
    });

    it("allows keeping same name", async () => {
      // Arrange
      const categoryId = faker.string.uuid();
      const currentCategory = fakeCategory({
        id: categoryId,
        userId,
        name: "Groceries",
      });

      mockCategoryRepository.findOneById.mockResolvedValue(currentCategory);
      mockCategoryRepository.update.mockImplementation(async (category) =>
        category.bumpVersion(),
      );

      // Act
      const result = await service.updateCategory(categoryId, userId, {
        name: "Groceries",
      });

      // Assert
      expect(result).toBeSuccess(
        expect.objectContaining({ name: "Groceries" }),
      );
      expect(mockCategoryRepository.update).toHaveBeenCalled();
      // No duplicate-name lookup when the name does not change
      expect(mockCategoryRepository.findManyByUserId).not.toHaveBeenCalled();
    });

    it("changes type when category has no active transactions", async () => {
      // Arrange
      const categoryId = faker.string.uuid();
      const existingCategory = fakeCategory({
        id: categoryId,
        userId,
        type: "EXPENSE",
      });

      // Category exists
      mockCategoryRepository.findOneById.mockResolvedValue(existingCategory);
      // Category has no active transactions
      mockTransactionRepository.hasTransactionsForCategory.mockResolvedValue(
        false,
      );
      // Persists and returns updated category
      mockCategoryRepository.update.mockImplementation(async (category) =>
        category.bumpVersion(),
      );

      // Act
      const result = await service.updateCategory(categoryId, userId, {
        type: "INCOME",
      });

      // Assert
      expect(result).toBeSuccess(expect.objectContaining({ type: "INCOME" }));
      expect(
        mockTransactionRepository.hasTransactionsForCategory,
      ).toHaveBeenCalledWith({ categoryId, userId });
      expect(mockCategoryRepository.update).toHaveBeenCalledWith(
        expect.objectContaining({ id: categoryId, type: "INCOME" }),
      );
    });

    it("updates category with active transactions when type does not change", async () => {
      // Arrange
      const categoryId = faker.string.uuid();
      const existingCategory = fakeCategory({
        id: categoryId,
        userId,
        type: "EXPENSE",
        excludeFromReports: false,
      });

      // Category exists
      mockCategoryRepository.findOneById.mockResolvedValue(existingCategory);
      // Category has active transactions
      mockTransactionRepository.hasTransactionsForCategory.mockResolvedValue(
        true,
      );
      // Persists and returns updated category
      mockCategoryRepository.update.mockImplementation(async (category) =>
        category.bumpVersion(),
      );

      // Act
      const result = await service.updateCategory(categoryId, userId, {
        name: "New Name",
        type: "EXPENSE",
        excludeFromReports: true,
      });

      // Assert
      expect(result).toBeSuccess(
        expect.objectContaining({
          name: "New Name",
          type: "EXPENSE",
          excludeFromReports: true,
        }),
      );
      expect(
        mockTransactionRepository.hasTransactionsForCategory,
      ).not.toHaveBeenCalled();
      expect(mockCategoryRepository.update).toHaveBeenCalled();
    });

    // Validation failures

    it("fails when category is not found", async () => {
      // Arrange
      const categoryId = faker.string.uuid();

      mockCategoryRepository.findOneById.mockResolvedValue(null);

      // Act
      const result = await service.updateCategory(categoryId, userId, {
        name: "New Name",
      });

      // Assert
      expect(result).toBeFailure("Category not found");
      expect(mockCategoryRepository.update).not.toHaveBeenCalled();
    });

    it("fails when model invariant is violated", async () => {
      // Arrange
      const categoryId = faker.string.uuid();
      const currentCategory = fakeCategory({ id: categoryId, userId });
      mockCategoryRepository.findOneById.mockResolvedValue(currentCategory);
      // Empty name triggers ModelError, which the service must expose as failure
      const input = { name: "" };

      // Act
      const result = await service.updateCategory(categoryId, userId, input);

      // Assert
      expect(result).toBeFailure(
        `Category name must be between ${NAME_MIN_LENGTH} and ${NAME_MAX_LENGTH} characters`,
      );
      expect(mockCategoryRepository.update).not.toHaveBeenCalled();
    });

    it("fails when updating archived category", async () => {
      // Arrange
      const categoryId = faker.string.uuid();
      // Archived category
      const currentCategory = fakeCategory({
        id: categoryId,
        userId,
        isArchived: true,
      });
      mockCategoryRepository.findOneById.mockResolvedValue(currentCategory);

      // Act
      const result = await service.updateCategory(categoryId, userId, {
        name: "New Name",
      });

      // Assert
      expect(result).toBeFailure("Cannot update archived category");
      expect(mockCategoryRepository.update).not.toHaveBeenCalled();
    });

    it("fails when updated name already exists for another category", async () => {
      // Arrange
      const categoryId = faker.string.uuid();
      const currentCategory = fakeCategory({
        id: categoryId,
        userId,
        name: "Utilities",
      });
      const otherCategory = fakeCategory({ userId, name: "Groceries" });

      mockCategoryRepository.findOneById.mockResolvedValue(currentCategory);
      // Another category already has the name "Groceries"
      mockCategoryRepository.findManyByUserId.mockResolvedValue([
        currentCategory,
        otherCategory,
      ]);

      // Act
      const result = await service.updateCategory(categoryId, userId, {
        name: "Groceries",
      });

      // Assert
      expect(result).toBeFailure('Category "Groceries" already exists');
      expect(mockCategoryRepository.update).not.toHaveBeenCalled();
    });

    it("fails when type changes and category has active transactions", async () => {
      // Arrange
      const categoryId = faker.string.uuid();
      const existingCategory = fakeCategory({
        id: categoryId,
        userId,
        type: "EXPENSE",
      });

      // Category exists
      mockCategoryRepository.findOneById.mockResolvedValue(existingCategory);
      // Category has active transactions
      mockTransactionRepository.hasTransactionsForCategory.mockResolvedValue(
        true,
      );

      // Act
      const result = await service.updateCategory(categoryId, userId, {
        type: "INCOME",
      });

      // Assert
      expect(result).toBeFailure(
        "Cannot change type of category with transactions",
      );
      expect(
        mockTransactionRepository.hasTransactionsForCategory,
      ).toHaveBeenCalledWith({ categoryId, userId });
      expect(mockCategoryRepository.update).not.toHaveBeenCalled();
    });
  });

  describe("deleteCategory", () => {
    // Happy path

    it("returns archived category", async () => {
      // Arrange
      const categoryId = faker.string.uuid();
      const currentCategory = fakeCategory({
        id: categoryId,
        userId,
        isArchived: false,
      });

      mockCategoryRepository.findOneById.mockResolvedValue(currentCategory);
      mockCategoryRepository.update.mockImplementation(async (category) =>
        category.bumpVersion(),
      );

      // Act
      const result = await service.deleteCategory(categoryId, userId);

      // Assert
      expect(result).toBeSuccess(expect.objectContaining({ isArchived: true }));
      expect(mockCategoryRepository.update).toHaveBeenCalledWith(
        expect.objectContaining({ id: categoryId, isArchived: true }),
      );
    });

    // Validation failures

    it("fails when category is not found", async () => {
      // Arrange
      const categoryId = faker.string.uuid();

      mockCategoryRepository.findOneById.mockResolvedValue(null);

      // Act
      const result = await service.deleteCategory(categoryId, userId);

      // Assert
      expect(result).toBeFailure("Category not found");
      expect(mockCategoryRepository.update).not.toHaveBeenCalled();
    });

    it("fails when category already archived", async () => {
      // Arrange
      const categoryId = faker.string.uuid();
      // Archived category
      const currentCategory = fakeCategory({
        id: categoryId,
        userId,
        isArchived: true,
      });

      mockCategoryRepository.findOneById.mockResolvedValue(currentCategory);

      // Act
      const result = await service.deleteCategory(categoryId, userId);

      // Assert
      expect(result).toBeFailure("Cannot archive archived category");
      expect(mockCategoryRepository.update).not.toHaveBeenCalled();
    });
  });
});

