import { faker } from "@faker-js/faker";
import { Failure, Success } from "ts-result";
import { type Mocked, beforeEach, describe, expect, it, vi } from "vitest";
import { CREATE_TRANSACTION_TOOL_NAME } from "../langchain/tools/create-transaction";
import { Agent, AgentTraceMessage } from "../ports/agent-types";
import { fakeTransaction } from "../utils/test-utils/models/transaction-fakes";
import { createMockTransactionService } from "../utils/test-utils/services/transaction-service-mocks";
import { CreateTransactionFromTextService } from "./create-transaction-from-text-service";
import { TransactionService } from "./transaction-service";

const createMockCreateTransactionAgent = (): Mocked<
  Agent<{ userId: string; isVoiceInput: boolean; today: string }>
> => ({
  invoke: vi.fn(),
});

describe("CreateTransactionFromTextService", () => {
  const userId = faker.string.uuid();
  const text = "coffee at starbucks for 5 euros";

  let mockCreateTransactionAgent: Mocked<
    Agent<{ userId: string; isVoiceInput: boolean; today: string }>
  >;
  let mockTransactionService: Mocked<TransactionService>;
  let service: CreateTransactionFromTextService;

  beforeEach(() => {
    mockCreateTransactionAgent = createMockCreateTransactionAgent();
    mockTransactionService = createMockTransactionService();

    service = new CreateTransactionFromTextService({
      createTransactionAgent: mockCreateTransactionAgent,
      transactionService: mockTransactionService,
    });

    vi.clearAllMocks();
  });

  describe("call", () => {
    // Happy path

    it("returns created transaction", async () => {
      // Arrange
      const transactionId = faker.string.uuid();
      const createdTransaction = fakeTransaction();

      // Agent successfully creates transaction
      mockCreateTransactionAgent.invoke.mockResolvedValue({
        answer: "OK",
        agentTrace: [],
        toolExecutions: [
          {
            tool: CREATE_TRANSACTION_TOOL_NAME,
            input: JSON.stringify({ amount: 5 }),
            output: JSON.stringify({
              success: true,
              data: { id: transactionId },
            }),
          },
        ],
      });

      // Fetching created transaction succeeds
      mockTransactionService.getTransactionById.mockResolvedValue(
        Success(createdTransaction),
      );

      // Act
      const result = await service.call({ userId, text });

      // Assert
      expect(result).toMatchObject({
        success: true,
        data: { transaction: createdTransaction },
      });
      expect(mockTransactionService.getTransactionById).toHaveBeenCalledWith(
        transactionId,
        userId,
      );
    });

    it("returns agentTrace from agent response", async () => {
      // Arrange
      const transactionId = faker.string.uuid();
      const agentTrace: AgentTraceMessage[] = [
        { type: "TEXT", content: "Thinking..." },
      ];

      // Agent returns thinking trace alongside tool execution
      mockCreateTransactionAgent.invoke.mockResolvedValue({
        answer: "OK",
        agentTrace,
        toolExecutions: [
          {
            tool: CREATE_TRANSACTION_TOOL_NAME,
            input: JSON.stringify({ amount: 5 }),
            output: JSON.stringify({
              success: true,
              data: { id: transactionId },
            }),
          },
        ],
      });

      // Fetching created transaction succeeds
      mockTransactionService.getTransactionById.mockResolvedValue(
        Success(fakeTransaction()),
      );

      // Act
      const result = await service.call({ userId, text });

      // Assert
      expect(result).toMatchObject({
        success: true,
        data: {
          agentTrace: expect.arrayContaining([
            { type: "TEXT", content: "Thinking..." },
          ]),
        },
      });
    });

    it("uses last createTransaction execution when multiple exist", async () => {
      // Arrange
      const firstTransactionId = faker.string.uuid();
      const lastTransactionId = faker.string.uuid();
      const createdTransaction = fakeTransaction();

      // Agent calls createTransaction twice — only last result is used
      mockCreateTransactionAgent.invoke.mockResolvedValue({
        answer: "OK",
        agentTrace: [],
        toolExecutions: [
          {
            tool: CREATE_TRANSACTION_TOOL_NAME,
            input: JSON.stringify({ amount: 4 }),
            output: JSON.stringify({
              success: true,
              data: { id: firstTransactionId },
            }),
          },
          {
            tool: CREATE_TRANSACTION_TOOL_NAME,
            input: JSON.stringify({ amount: 5 }),
            output: JSON.stringify({
              success: true,
              data: { id: lastTransactionId },
            }),
          },
        ],
      });

      // Fetching created transaction succeeds
      mockTransactionService.getTransactionById.mockResolvedValue(
        Success(createdTransaction),
      );

      // Act
      const result = await service.call({ userId, text });

      // Assert
      expect(result).toMatchObject({
        success: true,
        data: { transaction: createdTransaction },
      });
      expect(mockTransactionService.getTransactionById).toHaveBeenCalledWith(
        lastTransactionId,
        userId,
      );
    });

    describe("agent call parameters", () => {
      beforeEach(() => {
        // Agent successfully creates transaction
        mockCreateTransactionAgent.invoke.mockResolvedValue({
          answer: "OK",
          agentTrace: [],
          toolExecutions: [
            {
              tool: CREATE_TRANSACTION_TOOL_NAME,
              input: JSON.stringify({ amount: 5 }),
              output: JSON.stringify({
                success: true,
                data: { id: faker.string.uuid() },
              }),
            },
          ],
        });

        // Fetching created transaction succeeds
        mockTransactionService.getTransactionById.mockResolvedValue(
          Success(fakeTransaction()),
        );
      });

      it("passes trimmed text to agent", async () => {
        // Act
        await service.call({ userId, text: `    ${text}    ` });

        // Assert
        const [state] = mockCreateTransactionAgent.invoke.mock
          .calls[0] as unknown as [
          { messages: { content: string }[] },
          unknown,
        ];
        expect(state.messages[0]?.content).toContain(text);
      });

      it("passes userId in context", async () => {
        // Act
        await service.call({ userId, text });

        // Assert
        const [, config] = mockCreateTransactionAgent.invoke.mock.calls[0] as [
          unknown,
          { context: { userId: string } },
        ];
        expect(config.context.userId).toBe(userId);
      });

      it("passes today's date in context", async () => {
        // Act
        await service.call({ userId, text });

        // Assert
        const [, config] = mockCreateTransactionAgent.invoke.mock.calls[0] as [
          unknown,
          { context: { today: string } },
        ];
        expect(config.context.today).toMatch(/^\d{4}-\d{2}-\d{2}$/);
      });

      it("passes isVoiceInput false in context by default", async () => {
        // Act
        await service.call({ userId, text, isVoiceInput: false });

        // Assert
        const [, config] = mockCreateTransactionAgent.invoke.mock.calls[0] as [
          unknown,
          { context: { isVoiceInput: boolean } },
        ];
        expect(config.context.isVoiceInput).toBe(false);
      });

      it("passes isVoiceInput true in context when set", async () => {
        // Act
        await service.call({ userId, text, isVoiceInput: true });

        // Assert
        const [, config] = mockCreateTransactionAgent.invoke.mock.calls[0] as [
          unknown,
          { context: { isVoiceInput: boolean } },
        ];
        expect(config.context.isVoiceInput).toBe(true);
      });
    });

    // Validation failures

    it("returns failure when userId is empty", async () => {
      // Act
      const result = await service.call({ userId: "", text });

      // Assert
      expect(result).toMatchObject({
        success: false,
        error: { message: "User ID is required" },
      });
      expect(mockCreateTransactionAgent.invoke).not.toHaveBeenCalled();
    });

    it("returns failure when text is empty", async () => {
      // Act
      const result = await service.call({ userId, text: "" });

      // Assert
      expect(result).toMatchObject({
        success: false,
        error: { message: "Text is required" },
      });
      expect(mockCreateTransactionAgent.invoke).not.toHaveBeenCalled();
    });

    it("returns failure when text is only whitespace", async () => {
      // Act
      const result = await service.call({ userId, text: "   " });

      // Assert
      expect(result).toMatchObject({
        success: false,
        error: { message: "Text is required" },
      });
      expect(mockCreateTransactionAgent.invoke).not.toHaveBeenCalled();
    });

    // Dependency failures

    it("propagates error when agent throws", async () => {
      // Arrange

      // Agent is unavailable
      mockCreateTransactionAgent.invoke.mockRejectedValue(
        new Error("Agent unavailable"),
      );

      // Act & Assert
      await expect(service.call({ userId, text })).rejects.toThrow(
        "Agent unavailable",
      );
      expect(mockTransactionService.getTransactionById).not.toHaveBeenCalled();
    });

    it("returns failure when agent does not attempt to create transaction", async () => {
      // Arrange

      // Agent responds without invoking createTransaction tool
      mockCreateTransactionAgent.invoke.mockResolvedValue({
        answer: "I need more information.",
        agentTrace: [],
        toolExecutions: [],
      });

      // Act
      const result = await service.call({ userId, text });

      // Assert
      expect(result).toMatchObject({
        success: false,
        error: {
          message:
            "Agent did not attempt to create a transaction\nI need more information.",
        },
      });
      expect(mockTransactionService.getTransactionById).not.toHaveBeenCalled();
    });

    it("returns failure when tool output is not valid JSON", async () => {
      // Arrange

      // Agent invokes tool but output is malformed
      mockCreateTransactionAgent.invoke.mockResolvedValue({
        answer: undefined,
        agentTrace: [],
        toolExecutions: [
          {
            tool: CREATE_TRANSACTION_TOOL_NAME,
            input: JSON.stringify({}),
            output: "This is not valid JSON",
          },
        ],
      });

      // Act
      const result = await service.call({ userId, text });

      // Assert
      expect(result).toMatchObject({
        success: false,
        error: { message: "Response from agent is not valid JSON" },
      });
      expect(mockTransactionService.getTransactionById).not.toHaveBeenCalled();
    });

    it("returns failure when tool output does not match expected schema", async () => {
      // Arrange

      // Agent invokes tool but returns unexpected JSON shape
      mockCreateTransactionAgent.invoke.mockResolvedValue({
        answer: undefined,
        agentTrace: [],
        toolExecutions: [
          {
            tool: CREATE_TRANSACTION_TOOL_NAME,
            input: JSON.stringify({}),
            output: JSON.stringify({
              success: true,
              data: { currency: "EUR" }, // missing "id"
            }),
          },
        ],
      });

      // Act
      const result = await service.call({ userId, text });

      // Assert
      expect(result).toMatchObject({
        success: false,
        error: {
          message: "Response from agent does not match expected format",
        },
      });
      expect(mockTransactionService.getTransactionById).not.toHaveBeenCalled();
    });

    it("returns failure when tool reports transaction creation failed", async () => {
      // Arrange

      // Agent invokes tool but tool itself reports business failure
      mockCreateTransactionAgent.invoke.mockResolvedValue({
        answer: undefined,
        agentTrace: [],
        toolExecutions: [
          {
            tool: CREATE_TRANSACTION_TOOL_NAME,
            input: JSON.stringify({}),
            output: JSON.stringify({
              success: false,
              error: "Account not found",
            }),
          },
        ],
      });

      // Act
      const result = await service.call({ userId, text });

      // Assert
      expect(result).toMatchObject({
        success: false,
        error: { message: "Agent failed to create transaction" },
      });
      expect(mockTransactionService.getTransactionById).not.toHaveBeenCalled();
    });

    it("fails when created transaction cannot be fetched", async () => {
      // Arrange
      const transactionId = faker.string.uuid();

      // Agent successfully creates transaction
      mockCreateTransactionAgent.invoke.mockResolvedValue({
        answer: "OK",
        agentTrace: [],
        toolExecutions: [
          {
            tool: CREATE_TRANSACTION_TOOL_NAME,
            input: JSON.stringify({ amount: 5 }),
            output: JSON.stringify({
              success: true,
              data: { id: transactionId },
            }),
          },
        ],
      });

      // Fetching created transaction fails
      mockTransactionService.getTransactionById.mockResolvedValue(
        Failure("Transaction not found or doesn't belong to user"),
      );

      // Act
      const result = await service.call({ userId, text });

      // Assert
      expect(result).toMatchObject({
        success: false,
        error: {
          message: "Transaction not found or doesn't belong to user",
        },
      });
    });

    it("includes agentTrace in failure response", async () => {
      // Arrange

      // Agent responds with thinking trace but no tool call
      mockCreateTransactionAgent.invoke.mockResolvedValue({
        answer: undefined,
        agentTrace: [{ type: "TEXT", content: "Thinking..." }],
        toolExecutions: [],
      });

      // Act
      const result = await service.call({ userId, text });

      // Assert
      expect(result).toMatchObject({
        success: false,
        error: {
          agentTrace: [{ type: "TEXT", content: "Thinking..." }],
        },
      });
    });
  });
});

src/models/telegram-bot.test.ts.source:
import { faker } from "@faker-js/faker";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
  fakeConnectedTelegramBot,
  fakeCreateTelegramBotInput,
  fakePendingTelegramBot,
  fakeTelegramBot,
} from "../utils/test-utils/models/telegram-bot-fakes";
import { ModelError } from "./model-error";
import { TelegramBot } from "./telegram-bot";

describe("TelegramBot", () => {
  describe("create", () => {
    beforeEach(() => {
      vi.useFakeTimers().setSystemTime(new Date("2000-01-02T10:11:12.000Z"));
    });

    afterEach(() => {
      vi.useRealTimers();
    });

    // Happy path

    it("builds bot with all fields populated", () => {
      // Arrange
      const userId = faker.string.uuid();
      const input = fakeCreateTelegramBotInput({ userId, token: "12345" });

      // Act
      const result = TelegramBot.create(input, {
        idGenerator: () => "fixed-uuid",
        webhookSecretGenerator: () => "fixed-secret",
      });

      // Assert
      expect(result.toData()).toEqual({
        id: "fixed-uuid",
        userId,
        token: "12345",
        webhookSecret: "fixed-secret",
        status: "PENDING",
        isArchived: false,
        createdAt: "2000-01-02T10:11:12.000Z",
        updatedAt: "2000-01-02T10:11:12.000Z",
      });
    });

    it("trims token", () => {
      // Act
      const result = TelegramBot.create(
        fakeCreateTelegramBotInput({ token: "  12345  " }),
      );

      // Assert
      expect(result.token).toBe("12345");
    });

    it("uses default id generator when options omitted", () => {
      // Act
      const result = TelegramBot.create(fakeCreateTelegramBotInput());

      // Assert
      expect(result.id).toBeDefined();
    });

    it("uses default webhook secret generator when options omitted", () => {
      // Act
      const result = TelegramBot.create(fakeCreateTelegramBotInput());

      // Assert
      expect(result.webhookSecret).toBeDefined();
    });

    // Validation failures

    it("throws when token is empty", () => {
      // Act & Assert
      expect(() =>
        TelegramBot.create(fakeCreateTelegramBotInput({ token: "  " })),
      ).toThrow(new ModelError("Telegram bot token is required"));
    });
  });

  describe("fromPersistence", () => {
    // Happy path

    it("reconstructs instance from data", () => {
      // Arrange
      const data = fakeTelegramBot().toData();

      // Act
      const result = TelegramBot.fromPersistence(data);

      // Assert
      expect(result.toData()).toEqual(data);
    });

    // Validation failures

    it("throws when token is empty", () => {
      // Arrange
      const data = { ...fakeTelegramBot().toData(), token: "" };

      // Act & Assert
      expect(() => TelegramBot.fromPersistence(data)).toThrow(
        new ModelError("Telegram bot token is required"),
      );
    });

    it("throws when webhook secret is empty", () => {
      // Arrange
      const data = { ...fakeTelegramBot().toData(), webhookSecret: "" };

      // Act & Assert
      expect(() => TelegramBot.fromPersistence(data)).toThrow(
        new ModelError("Telegram bot webhook secret is required"),
      );
    });
  });

  describe("toData", () => {
    // Happy path

    it("returns plain object with all data fields", () => {
      // Arrange
      const data = fakeTelegramBot().toData();
      const bot = TelegramBot.fromPersistence(data);

      // Act & Assert
      expect(bot.toData()).toEqual(data);
    });
  });

  describe("connect", () => {
    beforeEach(() => {
      vi.useFakeTimers().setSystemTime(new Date("2000-01-02T10:11:12.000Z"));
    });

    afterEach(() => {
      vi.useRealTimers();
    });

    // Happy path

    it("sets status to CONNECTED", () => {
      // Arrange
      const existing = fakePendingTelegramBot();

      // Act
      const result = existing.connect();

      // Assert
      expect(result.status).toBe("CONNECTED");
    });

    it("sets updatedAt", () => {
      // Arrange
      const existing = fakePendingTelegramBot();

      // Act
      const result = existing.connect();

      // Assert
      expect(result.updatedAt).toBe("2000-01-02T10:11:12.000Z");
    });

    // Validation failures

    it("throws when bot is not PENDING", () => {
      // Arrange
      const existing = fakeConnectedTelegramBot();

      // Act & Assert
      expect(() => existing.connect()).toThrow(
        new ModelError("Cannot connect bot that is not pending"),
      );
    });
  });

  describe("disconnect", () => {
    beforeEach(() => {
      vi.useFakeTimers().setSystemTime(new Date("2000-01-02T10:11:12.000Z"));
    });

    afterEach(() => {
      vi.useRealTimers();
    });

    // Happy path

    it("sets status to DELETING", () => {
      // Arrange
      const existing = fakeConnectedTelegramBot();

      // Act
      const result = existing.disconnect();

      // Assert
      expect(result.status).toBe("DELETING");
    });

    it("sets updatedAt", () => {
      // Arrange
      const existing = fakeConnectedTelegramBot();

      // Act
      const result = existing.disconnect();

      // Assert
      expect(result.updatedAt).toBe("2000-01-02T10:11:12.000Z");
    });

    // Validation failures

    it("throws when bot is not CONNECTED", () => {
      // Arrange
      const existing = fakePendingTelegramBot();

      // Act & Assert
      expect(() => existing.disconnect()).toThrow(
        new ModelError("Cannot disconnect bot that is not connected"),
      );
    });
  });

  describe("archive", () => {
    beforeEach(() => {
      vi.useFakeTimers().setSystemTime(new Date("2000-01-02T10:11:12.000Z"));
    });

    afterEach(() => {
      vi.useRealTimers();
    });

    // Happy path

    it("sets isArchived to true", () => {
      // Arrange
      const existing = fakeTelegramBot({ isArchived: false });

      // Act
      const result = existing.archive();

      // Assert
      expect(result.isArchived).toBe(true);
    });

    it("sets updatedAt", () => {
      // Arrange
      const existing = fakeTelegramBot({ isArchived: false });

      // Act
      const result = existing.archive();

      // Assert
      expect(result.updatedAt).toBe("2000-01-02T10:11:12.000Z");
    });

    // Validation failures

    it("throws on already archived bot", () => {
      // Arrange
      const existing = fakeTelegramBot({ isArchived: true });

      // Act & Assert
      expect(() => existing.archive()).toThrow(
        new ModelError("Cannot archive archived telegram bot"),
      );
    });
  });
});

