import { describe, expect, it } from "vitest";
import { SUPPORTED_CURRENCIES, isSupportedCurrency } from "./currency";

describe("SUPPORTED_CURRENCIES", () => {
  it("is non-empty", () => {
    // Act & Assert
    expect(SUPPORTED_CURRENCIES.length).toBeGreaterThan(0);
  });

  it("includes EUR and USD", () => {
    // Act & Assert
    expect(SUPPORTED_CURRENCIES).toContain("EUR");
    expect(SUPPORTED_CURRENCIES).toContain("USD");
  });

  it("is sorted alphabetically", () => {
    // Arrange
    const sorted = [...SUPPORTED_CURRENCIES].sort();

    // Act & Assert
    expect(SUPPORTED_CURRENCIES).toEqual(sorted);
  });
});

describe("isSupportedCurrency", () => {
  // Happy path

  it("returns true for USD", () => {
    // Act & Assert
    expect(isSupportedCurrency("USD")).toBe(true);
  });

  it("returns true for EUR", () => {
    // Act & Assert
    expect(isSupportedCurrency("EUR")).toBe(true);
  });

  // Validation failures

  it("returns false for non-ISO code", () => {
    // Act & Assert
    expect(isSupportedCurrency("INVALID")).toBe(false);
  });

  it("returns false for lowercase input", () => {
    // Act & Assert
    expect(isSupportedCurrency("usd")).toBe(false);
  });

  it("returns false for input with surrounding whitespace", () => {
    // Act & Assert
    expect(isSupportedCurrency(" USD ")).toBe(false);
  });

  it("returns false for empty string", () => {
    // Act & Assert
    expect(isSupportedCurrency("")).toBe(false);
  });
});

src/lambdas/bootstrap.test.ts.source:
import {
  GetParametersCommand,
  GetParametersCommandOutput,
  SSMClient,
} from "@aws-sdk/client-ssm";
import { type Mock, beforeEach, describe, expect, it, vi } from "vitest";
import { injectRuntimeEnv } from "./bootstrap";

vi.mock("@aws-sdk/client-ssm", async () => {
  const actual = await vi.importActual<typeof import("@aws-sdk/client-ssm")>(
    "@aws-sdk/client-ssm",
  );

  return {
    ...actual,
    SSMClient: vi.fn(),
  };
});

describe("injectRuntimeEnv", () => {
  let sendMock: Mock<(command: unknown) => Promise<GetParametersCommandOutput>>;

  beforeEach(() => {
    vi.clearAllMocks();

    sendMock =
      vi.fn<(command: unknown) => Promise<GetParametersCommandOutput>>();

    (SSMClient as Mock).mockImplementation(function () {
      return { send: sendMock };
    });
  });

  // Happy path

  it("fetches SSM parameters and injects env vars", async () => {
    // Arrange
    const processEnv: NodeJS.ProcessEnv = {
      AWS_LAMBDA_FUNCTION_NAME: "web-lambda",
      NODE_ENV: "test",
    };

    const bindings = [
      { ssmPath: "/budget/test/feature-x", envVar: "FEATURE_X" },
      { ssmPath: "/budget/test/feature-y", envVar: "FEATURE_Y" },
    ];

    // SSM returns values for both requested parameters
    sendMock.mockResolvedValue({
      $metadata: {},
      Parameters: [
        { Name: "/budget/test/feature-x", Value: "value-x" },
        { Name: "/budget/test/feature-y", Value: "value-y" },
      ],
    });

    // Act
    await injectRuntimeEnv(processEnv, () => bindings);

    // Assert
    expect(processEnv["FEATURE_X"]).toBe("value-x");
    expect(processEnv["FEATURE_Y"]).toBe("value-y");
    expect(sendMock).toHaveBeenCalledTimes(1);
  });

  it("calls SSM multiple times when bindings exceed batch size", async () => {
    // Arrange
    const processEnv: NodeJS.ProcessEnv = {
      AWS_LAMBDA_FUNCTION_NAME: "web-lambda",
      NODE_ENV: "test",
    };

    const bindings = Array.from({ length: 15 }, (_, i) => ({
      ssmPath: `/budget/test/feature-${i}`,
      envVar: `FEATURE_${i}`,
    }));

    // SSM echoes each requested name back as a parameter value
    sendMock.mockImplementation(async (command) => {
      const names = (command as GetParametersCommand).input.Names ?? [];
      return {
        $metadata: {},
        Parameters: names.map((name) => ({
          Name: name,
          Value: `value-${name}`,
        })),
      };
    });

    // Act
    await injectRuntimeEnv(processEnv, () => bindings);

    // Assert
    for (const binding of bindings) {
      expect(processEnv[binding.envVar]).toBe(`value-${binding.ssmPath}`);
    }

    expect(sendMock).toHaveBeenCalledTimes(2);

    const firstCallNames = (sendMock.mock.calls[0]?.[0] as GetParametersCommand)
      .input.Names;
    const secondCallNames = (
      sendMock.mock.calls[1]?.[0] as GetParametersCommand
    ).input.Names;

    expect(firstCallNames).toHaveLength(10);
    expect(secondCallNames).toHaveLength(5);
  });

  it("only sets found params when SSM returns partial response", async () => {
    // Arrange
    const processEnv: NodeJS.ProcessEnv = {
      AWS_LAMBDA_FUNCTION_NAME: "web-lambda",
      NODE_ENV: "test",
    };

    const bindings = [
      { ssmPath: "/budget/test/feature-x", envVar: "FEATURE_X" },
      { ssmPath: "/budget/test/feature-y", envVar: "FEATURE_Y" },
      { ssmPath: "/budget/test/feature-z", envVar: "FEATURE_Z" },
    ];

    // SSM returns two of three; third reported as invalid
    sendMock.mockResolvedValue({
      $metadata: {},
      Parameters: [
        { Name: "/budget/test/feature-x", Value: "value-x" },
        { Name: "/budget/test/feature-z", Value: "value-z" },
      ],
      InvalidParameters: ["/budget/test/feature-y"],
    });

    // Act
    await injectRuntimeEnv(processEnv, () => bindings);

    // Assert
    expect(processEnv["FEATURE_X"]).toBe("value-x");
    expect(processEnv["FEATURE_Y"]).toBeUndefined();
    expect(processEnv["FEATURE_Z"]).toBe("value-z");
  });

  it("requests SSM parameters with decryption enabled", async () => {
    // Arrange
    const processEnv: NodeJS.ProcessEnv = {
      AWS_LAMBDA_FUNCTION_NAME: "web-lambda",
      NODE_ENV: "test",
    };
    const bindings = [
      { ssmPath: "/budget/test/feature-x", envVar: "FEATURE_X" },
    ];

    // SSM returns nothing; test only inspects outgoing command
    sendMock.mockResolvedValue({ $metadata: {}, Parameters: [] });

    // Act
    await injectRuntimeEnv(processEnv, () => bindings);

    // Assert
    const command = sendMock.mock.calls[0]?.[0] as GetParametersCommand;
    expect(command.input.WithDecryption).toBe(true);
  });

  // Validation failures

  it("skips SSM fetch when not running on Lambda", async () => {
    // Arrange
    const processEnv: NodeJS.ProcessEnv = { NODE_ENV: "test" };
    const bindings = [
      { ssmPath: "/budget/test/feature-x", envVar: "FEATURE_X" },
    ];

    // Act
    await injectRuntimeEnv(processEnv, () => bindings);

    // Assert
    expect(processEnv["FEATURE_X"]).toBeUndefined();
    expect(sendMock).not.toHaveBeenCalled();
  });

  it("skips SSM fetch when NODE_ENV is unset", async () => {
    // Arrange
    const processEnv: NodeJS.ProcessEnv = {
      AWS_LAMBDA_FUNCTION_NAME: "web-lambda",
    };
    const bindings = [
      { ssmPath: "/budget/test/feature-x", envVar: "FEATURE_X" },
    ];

    // Act
    await injectRuntimeEnv(processEnv, () => bindings);

    // Assert
    expect(processEnv["FEATURE_X"]).toBeUndefined();
    expect(sendMock).not.toHaveBeenCalled();
  });

  it("does not overwrite env vars when already set", async () => {
    // Arrange
    const processEnv: NodeJS.ProcessEnv = {
      AWS_LAMBDA_FUNCTION_NAME: "web-lambda",
      NODE_ENV: "test",
      FEATURE_X: "preset",
    };

    const bindings = [
      { ssmPath: "/budget/test/feature-x", envVar: "FEATURE_X" },
    ];

    // SSM returns value that should be ignored in favor of existing env var
    sendMock.mockResolvedValue({
      $metadata: {},
      Parameters: [{ Name: "/budget/test/feature-x", Value: "new-value" }],
    });

    // Act
    await injectRuntimeEnv(processEnv, () => bindings);

    // Assert
    expect(processEnv["FEATURE_X"]).toBe("preset");
  });

  it("skips SSM fetch when bindings are empty", async () => {
    // Arrange
    const processEnv: NodeJS.ProcessEnv = {
      AWS_LAMBDA_FUNCTION_NAME: "web-lambda",
      NODE_ENV: "test",
    };

    // Act
    await injectRuntimeEnv(processEnv, () => []);

    // Assert
    expect(sendMock).not.toHaveBeenCalled();
  });
});

